// Sane first-look defaults for every FX (mirrors the AddFX menu values; used by the Ctrl+Space console)
static void InitFXDefaults(int type, FXParams& fx){
    fx.type = type; fx.enabled = true;
    for(int i = 0; i < 8; i++) fx.p[i] = 0.0f;
    switch(type){
    case FX_RGB_SPLIT: fx.p[0]=6.0f; fx.p[1]=45.0f; break;
    case FX_GAUSSIAN_BLUR: fx.p[0]=10.0f; break;
    case FX_DIRECTIONAL_BLUR: fx.p[0]=12.0f; break;
    case FX_ZOOM_BLUR: fx.p[0]=8.0f; break;
    case FX_MOSAIC: fx.p[0]=12.0f; break;
    case FX_SHAKE: fx.p[0]=2.0f; fx.p[1]=8.0f; break;
    case FX_VIGNETTE: fx.p[0]=0.8f; fx.p[1]=0.4f; break;
    case FX_SHARPEN: fx.p[0]=0.5f; break;
    case FX_EDGE_DETECT: fx.p[0]=1.0f; break;
    case FX_THRESHOLD: fx.p[0]=0.5f; break;
    case FX_CROP: fx.p[0]=0.1f; fx.p[1]=0.1f; fx.p[2]=0.1f; fx.p[3]=0.1f; break;
    case FX_TURBULENCE: fx.p[0]=4.0f; fx.p[1]=0.5f; break;
    case FX_WAVE_WARP: fx.p[0]=2.0f; fx.p[1]=0.5f; break;
    case FX_RIPPLE: fx.p[0]=0.5f; break;
    case FX_TWIRL: fx.p[0]=0.5f; break;
    case FX_FISHEYE: fx.p[0]=0.5f; break;
    case FX_KALEIDOSCOPE: fx.p[0]=6.0f; break;
    case FX_GLOW: fx.p[0]=8.0f; fx.p[1]=1.0f; fx.p[2]=0.7f; break;
    case FX_OUTLINE: fx.p[0]=2.0f; break;
    case FX_SHADOW: fx.p[0]=4.0f; fx.p[1]=4.0f; fx.p[3]=0.75f; break;
    case FX_GRADIENT: fx.p[6]=45.0f; fx.p[7]=0.5f; break;
    case FX_HALFTONE: fx.p[0]=4.0f; break;
    case FX_GRID: fx.p[0]=10.0f; fx.p[4]=0.5f; break;
    case FX_GHOST: fx.p[0]=0.5f; break;
    case FX_CHROMATIC: fx.p[0]=4.0f; break;
    case FX_PIXELATE: fx.p[0]=8.0f; break;
    case FX_POSTERIZE: fx.p[0]=4.0f; break;
    case FX_COLOR_MATRIX: fx.p[0]=1.0f; break;
    case FX_WIND: fx.p[0]=8.0f; fx.p[1]=1.0f; break;
    case FX_LENS_DISTORT: fx.p[0]=0.2f; break;
    case FX_PINCUSHION: fx.p[0]=0.3f; break;
    case FX_BARREL: fx.p[0]=0.3f; break;
    case FX_FILM_GRAIN: fx.p[0]=0.25f; break;
    case FX_MOTION_BLUR: fx.p[0]=8.0f; break;
    case FX_LETTERBOX: fx.p[0]=0.12f; fx.p[1]=0.12f; break;
    case FX_LUT_COLOR: fx.p[3]=1.0f; break;
    case FX_SMART_DEPTH_BLUR: fx.p[0]=12.0f; fx.p[1]=0.5f; fx.p[2]=0.2f; break;
    case FX_MOTION_TILE: fx.p[0]=100.0f; fx.p[2]=100.0f; break;
    default: break;
    }
}

