// ============ Data Model: Multi-Track Timeline & Non-Overlapping Layers ============
enum ItemType {
    ITEM_MEDIA = 0,
    ITEM_TEXT = 1
};

struct ImageData{int w=0,h=0;unsigned int tex=0;unsigned char*px=nullptr;std::string path;};

struct Camera{
    float zoom=1.0f; // Scale: 1.0f = 100% native fit size
    float px=0.0f;   // Position X offset (-2.0 .. +2.0)
    float py=0.0f;   // Position Y offset (-2.0 .. +2.0)
    float rot=0.0f;  // Rotation in radians
};

static Camera CamInterp(const Camera&a,const Camera&b,float t){
    Camera c;
    c.zoom=a.zoom+(b.zoom-a.zoom)*t;
    c.px=a.px+(b.px-a.px)*t;
    c.py=a.py+(b.py-a.py)*t;
    c.rot=a.rot+(b.rot-a.rot)*t;
    return c;
}

// AE Transform Keyframe
// AE-exact per-property keys: each prop owns an independent key list
struct Key1D{
    float time=0.0f; float value=0.0f;
    int easeType=1; // OUT curve of this key (shapes the segment leaving it)
    float bezCP[4]={0.25f, 0.10f, 0.25f, 1.00f};
    bool hold=false; // HOLD: value stays frozen until the next key (AE square key)
    int inEaseType=0; // IN curve (shapes arrival into this key); 0 = Linear = old out-only behavior
    float inBezCP[4]={0.0f, 0.0f, 1.0f, 1.00f};
};
struct Key2D{
    float time=0.0f; float x=0.0f, y=0.0f;
    int easeType=1;
    float bezCP[4]={0.25f, 0.10f, 0.25f, 1.00f};
    bool hold=false;
    int inEaseType=0;
    float inBezCP[4]={0.0f, 0.0f, 1.00f, 1.00f};
};
// Combined segment curve from k1's OUT handles + k2's IN handles (effectcraft ease_progress, CP form):
// combined P1 = k1.out, P2 = (1-k2.inX, 1-k2.inY). Either side linear (=chord) leaves the other side exact.
static void SegEaseCP(const float o[4], const float i[4], float out[4]){
    out[0]=o[0]; out[1]=o[1]; out[2]=1.0f-i[0]; out[3]=1.0f-i[1];
}

struct ColorGrade{float bright=0.0f,contrast=0.0f,sat=1.0f;};

// Multi-Track Timeline Item (Can be Media footage or Dedicated Text Layer)
struct TimelineItem{
    ItemType type = ITEM_MEDIA;
    int track = 0;          // Track / Layer index (0 = bottom background, 1, 2, 3...)
    float startTime = 0.0f; // Start timestamp on timeline (seconds)
    float duration = 2.5f;  // Duration on timeline (seconds)
    float speed = 1.0f;     // Playback speed
    float srcOff = 0.0f;    // media-time offset from trim-left (video/text would otherwise restart at the head)
    bool visible = true;    // Layer visibility toggle
    bool expanded = false;  // AE-style timeline twirl dropdown
    bool motionBlur = false; // Motion blur toggle
    int shutterAngle = 180; // Shutter angle (90, 180, 270, 360, 450, 540, custom)
    float customShutter = 180.0f;
    float opacity = 1.0f;

    // Media properties
    int imageIdx = -1;
    int videoIdx = -1;

    // Text Layer properties (for ITEM_TEXT)
    char textContent[256] = "Modern Title";
    int fontIdx = 0;
    float fontSize = 72.0f;
    float textColor[3] = {1.0f, 1.0f, 1.0f};
    float textAlpha = 1.0f;
    TextAnimParams anim;

    // Transform & Keyframing (Works for BOTH Media and Text Layers!)
    Camera cam;
    bool kenBurns = false; // any-keys cache (kept for old-file compat)
    std::vector<Key2D> kPos;   // Position keys (x, y)
    std::vector<Key1D> kScale; // Scale keys (zoom)
    std::vector<Key1D> kRot;   // Rotation keys (radians)
    std::vector<Key1D> kOp;    // Opacity keys (slider value)

    // Color & FX Stack (Works for BOTH Media and Text Layers!)
    ColorGrade color;
    std::vector<FXParams> fx;

    int transType = TRANS_NONE;
    float transDur = 0.3f;
};

typedef TimelineItem Clip;



