struct RealProjectInfo {
    std::string filename;
    std::string title;
    int resW = 1920;
    int resH = 1080;
    float fps = 30.0f;
    int clipCount = 0;
    float duration = 0.0f;
    std::string modifiedTime;
    uintmax_t fileSize = 0;
};

static std::vector<RealProjectInfo> g_RealProjects;
static std::string g_RealGpuRenderer = "";
static std::string g_RealGpuVendor = "";
static std::string g_RealGlVersion = "";

static void ScanRealProjects(){
    g_RealProjects.clear();
    WIN32_FIND_DATAA fd;
    HANDLE hFind = FindFirstFileA("*.aie", &fd);
    if(hFind != INVALID_HANDLE_VALUE){
        do {
            if(!(fd.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY)){
                RealProjectInfo pi;
                pi.filename = fd.cFileName;
                pi.title = fd.cFileName;
                if(pi.title.size() > 4 && pi.title.substr(pi.title.size() - 4) == ".aie"){
                    pi.title = pi.title.substr(0, pi.title.size() - 4);
                }
                
                FILETIME ft = fd.ftLastWriteTime;
                SYSTEMTIME stUTC, stLocal;
                FileTimeToSystemTime(&ft, &stUTC);
                SystemTimeToTzSpecificLocalTime(NULL, &stUTC, &stLocal);
                char timeBuf[64];
                snprintf(timeBuf, sizeof timeBuf, "%04d-%02d-%02d %02d:%02d",
                         stLocal.wYear, stLocal.wMonth, stLocal.wDay, stLocal.wHour, stLocal.wMinute);
                pi.modifiedTime = timeBuf;
                pi.fileSize = ((uint64_t)fd.nFileSizeHigh << 32) | fd.nFileSizeLow;

                FILE* f = fopen(fd.cFileName, "r");
                if(f){
                    char line[256];
                    while(fgets(line, sizeof line, f)){
                        if(strncmp(line, "RES ", 4) == 0){
                            sscanf(line + 4, "%d %d", &pi.resW, &pi.resH);
                        }else if(strncmp(line, "FPS ", 4) == 0){
                            sscanf(line + 4, "%f", &pi.fps);
                        }else if(strncmp(line, "CLIPS ", 6) == 0){
                            sscanf(line + 6, "%d", &pi.clipCount);
                        }else if(strncmp(line, "ITEM ", 5) == 0){
                            int tr, ty; float inP, dur, sp;
                            if(sscanf(line + 5, "%d %d %f %f %f", &tr, &ty, &inP, &dur, &sp) >= 4){
                                if(inP + dur > pi.duration) pi.duration = inP + dur;
                            }
                        }
                    }
                    fclose(f);
                }
                if(pi.duration <= 0.0f) pi.duration = 6.0f;
                g_RealProjects.push_back(pi);
            }
        } while(FindNextFileA(hFind, &fd));
        FindClose(hFind);
    }
}

