        if(g_Redo.size() > 50) g_Redo.erase(g_Redo.begin());
        g_Clips = g_Undo.back();
        g_Undo.pop_back();
        if(g_SelClip >= (int)g_Clips.size()) g_SelClip = (int)g_Clips.size() - 1;
        g_SelMulti.clear();
        g_Dirty = true;
