// Calculate dimensions from quality & aspect ratio
static void GetDimensionsForQualityAspect(int qual, int aspect, int& outW, int& outH){
    int baseDim = 1080;
    if(qual == QUAL_1080P) baseDim = 1080;
    else if(qual == QUAL_720P) baseDim = 720;
    else if(qual == QUAL_540P) baseDim = 540;
    else if(qual == QUAL_480P) baseDim = 480;
    else if(qual == QUAL_360P) baseDim = 360;
    else if(qual == QUAL_1440P) baseDim = 1440;
    else if(qual == QUAL_4K) baseDim = 2160;

    switch(aspect){
    case ASPECT_16_9:
        outH = baseDim;
        outW = (int)roundf(baseDim * (16.0f / 9.0f));
        break;
    case ASPECT_9_16:
        outW = baseDim;
        outH = (int)roundf(baseDim * (16.0f / 9.0f));
        break;
    case ASPECT_1_1:
        outW = baseDim;
        outH = baseDim;
        break;
    case ASPECT_4_3:
        outH = baseDim;
        outW = (int)roundf(baseDim * (4.0f / 3.0f));
        break;
    case ASPECT_3_4:
        outW = baseDim;
        outH = (int)roundf(baseDim * (4.0f / 3.0f));
        break;
    case ASPECT_4_5:
        outW = baseDim;
        outH = (int)roundf(baseDim * (5.0f / 4.0f));
        break;
    case ASPECT_21_9:
        outH = baseDim;
        outW = (int)roundf(baseDim * (21.0f / 9.0f));
        break;
    default:
        outW = 1920; outH = 1080; break;
    }
    outW = (outW / 2) * 2;
    outH = (outH / 2) * 2;
}

