// ============ Mathematically Exact 1:1 Cubic Bezier Engine ============
static float BezierX(float t, float x1, float x2){
    float u = 1.0f - t;
    return 3.0f * u * u * t * x1 + 3.0f * u * t * t * x2 + t * t * t;
}

static float BezierY(float t, float y1, float y2){
    float u = 1.0f - t;
    return 3.0f * u * u * t * y1 + 3.0f * u * t * t * y2 + t * t * t;
}

static float SolveBezierY(float x, const float cp[4]){
    x = clampf(x, 0.0f, 1.0f);
    float t = x;
    float x1 = cp[0], y1 = cp[1], x2 = cp[2], y2 = cp[3];
    
    for(int i = 0; i < 8; i++){
        float curX = BezierX(t, x1, x2) - x;
        if(fabsf(curX) < 1e-4f) break;
        float u = 1.0f - t;
        float dX = 3.0f * u * u * x1 + 6.0f * u * t * (x2 - x1) + 3.0f * t * t * (1.0f - x2);
        if(fabsf(dX) < 1e-5f) break;
        t -= curX / dX;
        t = clampf(t, 0.0f, 1.0f);
    }
    return BezierY(t, y1, y2);
}

