// ============ micro-animation tween kit (popups, console, view fades) ============
static double AnimNowSec(){ LARGE_INTEGER f, c; QueryPerformanceFrequency(&f); QueryPerformanceCounter(&c); return (double)c.QuadPart / (double)f.QuadPart; }
static float EaseOutCubic(float t){ t = std::max(0.0f, std::min(1.0f, t)); float u = 1.0f - t; return 1.0f - u*u*u; }
static std::unordered_map<std::string, double> s_PopupT0; // first-seen time per popup name
static float PopupEnterAlpha(const char* name){ // 0→1 over 150ms from first open frame; callers push it as window Alpha
    if(!ImGui::IsPopupOpen(name)){ s_PopupT0.erase(name); return 1.0f; }
    double now = AnimNowSec();
    auto it = s_PopupT0.find(name);
    if(it == s_PopupT0.end()){ s_PopupT0[name] = now; return 0.0f; }
    return EaseOutCubic((float)((now - it->second) / 0.15));
}
static void DrawViewFade(){ // 180ms black dip on home<->studio switches (covers the layout pop)
    if(g_ScreenshotMode) return; // captures fire on frame 3: never dim the test path
    static int s_LastAppState = -1;
    static double s_ViewT0 = 0.0;
    if((int)g_AppState != s_LastAppState){ s_LastAppState = (int)g_AppState; s_ViewT0 = AnimNowSec(); }
    float vk = 1.0f - EaseOutCubic((float)((AnimNowSec() - s_ViewT0) / 0.18));
    if(vk > 0.004f){
        ImDrawList* fg = ImGui::GetForegroundDrawList();
        ImVec2 v0 = ImGui::GetMainViewport()->Pos;
        ImVec2 vsz = ImGui::GetMainViewport()->Size;
        fg->AddRectFilled(v0, ImVec2(v0.x + vsz.x, v0.y + vsz.y), IM_COL32(0, 0, 0, (int)(vk * 255.0f)));
    }
}

// ============ helpers ============
// Frame-accurate quantization (Blurrr-style)
inline float SnapToFrame(float t, float fps = 0.0f){
    if(fps <= 0.0f) fps = g_FPS > 0.0f ? g_FPS : 30.0f;
    return std::floor(t * fps + 0.5f) / fps;
}
inline int TimeToFrames(float t, float fps = 0.0f){
    if(fps <= 0.0f) fps = g_FPS > 0.0f ? g_FPS : 30.0f;
    return (int)std::floor(t * fps + 0.5f);
}
inline void FormatFrameTimecode(char* buf, size_t bufSz, float t, float fps = 0.0f){
    if(fps <= 0.0f) fps = g_FPS > 0.0f ? g_FPS : 30.0f;
    int totalF = (int)std::floor(t * fps + 0.5f);
    if(totalF < 0) totalF = 0;
    int ifps = (int)fps;
    if(ifps < 1) ifps = 30;
    int secs = (totalF / ifps) % 60;
    int mins = (totalF / (ifps * 60)) % 60;
    int frms = totalF % ifps;
    snprintf(buf, bufSz, "%02d:%02d:%02df", mins, secs, frms);
}

static float ClipDur(int i){if(i<0||i>=(int)g_Clips.size())return 0;return g_Clips[i].duration*std::max(0.1f,g_Clips[i].speed);}
static float TotalDur(){
    float maxT = 0.0f;
    for(const auto& c : g_Clips){
        float endT = c.startTime + c.duration * std::max(0.1f, c.speed);
        if(endT > maxT) maxT = endT;
    }
    return std::max(maxT, 5.0f);
}

enum KeyPropBits{ KP_POS = 1, KP_SCALE = 2, KP_ROT = 4, KP_OP = 8 };
static const char* KeyPropNames[4] = {"Position", "Scale", "Rotation", "Opacity"};

template<typename K> static void KeySegCP(const K& k1, const K& k2, float out[4]){
    const float* o = (k1.easeType >= 0 && k1.easeType < g_EaseCount) ? g_EasePresets[k1.easeType].defaultBez : k1.bezCP;
    const float* i = (k2.inEaseType >= 0 && k2.inEaseType < g_EaseCount) ? g_EasePresets[k2.inEaseType].defaultBez : k2.inBezCP;
    SegEaseCP(o, i, out);
}

// ponytail: AE-exact — every property interpolates its own independent key list
static float InterpKeys1D(const std::vector<Key1D>& ks, float localTime, float base){
    if(ks.empty()) return base;
    if(ks.size() == 1) return ks[0].value;
    if(localTime <= ks.front().time) return ks.front().value;
    if(localTime >= ks.back().time) return ks.back().value;
    for(size_t i = 0; i + 1 < ks.size(); i++){
        const auto& k1 = ks[i];
        const auto& k2 = ks[i+1];
        if(localTime >= k1.time && localTime <= k2.time){
            if(k1.hold) return k1.value; // HOLD: frozen until the next key
            float dt = k2.time - k1.time;
            if(dt <= 0.0001f) return k1.value;
            float u = (localTime - k1.time) / dt;
            float cp[4]; KeySegCP(k1, k2, cp);
            return k1.value + (k2.value - k1.value) * SolveBezierY(u, cp);
        }
    }
    return base;
}

static Camera EvaluateClipTransform(const TimelineItem& c, float localTime){
    Camera res = c.cam;
    if(!c.kPos.empty()){
        if(c.kPos.size() == 1){ res.px = c.kPos[0].x; res.py = c.kPos[0].y; }
        else if(localTime <= c.kPos.front().time){ res.px = c.kPos.front().x; res.py = c.kPos.front().y; }
        else if(localTime >= c.kPos.back().time){ res.px = c.kPos.back().x; res.py = c.kPos.back().y; }
        else for(size_t i = 0; i + 1 < c.kPos.size(); i++){
            const auto& k1 = c.kPos[i];
            const auto& k2 = c.kPos[i+1];
            if(localTime >= k1.time && localTime <= k2.time){
                if(k1.hold){ res.px = k1.x; res.py = k1.y; break; }
                float dt = k2.time - k1.time;
                float u = (dt <= 0.0001f) ? 0.0f : (localTime - k1.time) / dt;
                float cp[4]; KeySegCP(k1, k2, cp);
                float e = SolveBezierY(u, cp);
                res.px = k1.x + (k2.x - k1.x) * e;
                res.py = k1.y + (k2.y - k1.y) * e;
                break;
            }
        }
    }
    if(!c.kScale.empty()) res.zoom = InterpKeys1D(c.kScale, localTime, c.cam.zoom);
    if(!c.kRot.empty()) res.rot = InterpKeys1D(c.kRot, localTime, c.cam.rot);
    return res;
}

static float EvaluateClipOpacity(const TimelineItem& c, float localTime){
    return InterpKeys1D(c.kOp, localTime, c.textAlpha);
}

static void RefreshKenBurns(TimelineItem& c){
    c.kenBurns = !c.kPos.empty() || !c.kScale.empty() || !c.kRot.empty() || !c.kOp.empty();
}

template<typename K> static int KeyIndexAt(const std::vector<K>& ks, float t, float th = 0.06f){
    for(int i = 0; i < (int)ks.size(); i++) if(fabsf(ks[i].time - t) <= th) return i;
    return -1;
}

template<typename K> static void SortKeys(std::vector<K>& ks){
    std::sort(ks.begin(), ks.end(), [](const K& a, const K& b){ return a.time < b.time; });
}

template<typename K> static void SplitKeyList(const std::vector<K>& src, float local, std::vector<K>& L, std::vector<K>& R){
    for(auto& k : src){
        if(k.time <= local) L.push_back(k);
        if(k.time >= local){ K rk = k; rk.time = k.time - local; R.push_back(rk); }
    }
}

static void UpsertPosKey(TimelineItem& c, float local, float x, float y){
    local = clampf(local, 0.0f, c.duration);
    int idx = KeyIndexAt(c.kPos, local, 0.05f);
    if(idx >= 0){ c.kPos[idx].x = x; c.kPos[idx].y = y; }
    else{ Key2D nk; nk.time = local; nk.x = x; nk.y = y; nk.easeType = g_SelectedEase; memcpy(nk.bezCP, g_BezCP, sizeof g_BezCP); c.kPos.push_back(nk); SortKeys(c.kPos); }
}

static void UpsertKey1D(std::vector<Key1D>& ks, float local, float v, float dur){
    local = clampf(local, 0.0f, dur);
    int idx = KeyIndexAt(ks, local, 0.05f);
    if(idx >= 0){ ks[idx].value = v; }
    else{ Key1D nk; nk.time = local; nk.value = v; nk.easeType = g_SelectedEase; memcpy(nk.bezCP, g_BezCP, sizeof g_BezCP); ks.push_back(nk); SortKeys(ks); }
}

// ponytail: per-prop key count / time accessors so lane/jump/snap code stays flat
static int PropKeyCount(const TimelineItem& c, int p){
    return p == 0 ? (int)c.kPos.size() : p == 1 ? (int)c.kScale.size() : p == 2 ? (int)c.kRot.size() : (int)c.kOp.size();
}
static float PropKeyTime(const TimelineItem& c, int p, int i){
    return p == 0 ? c.kPos[i].time : p == 1 ? c.kScale[i].time : p == 2 ? c.kRot[i].time : c.kOp[i].time;
}
static bool PropKeyHold(const TimelineItem& c, int p, int i){ // AE square key: holds its value until the next key
    return p == 0 ? c.kPos[i].hold : p == 1 ? c.kScale[i].hold : p == 2 ? c.kRot[i].hold : c.kOp[i].hold;
}
static int SelKeyEaseType(const TimelineItem& c){ // OUT-ease of the selected key, or -2 when no key is selected
    if(g_SelKey < 0 || g_SelKeyProp < 0 || g_SelKeyProp > 3 || g_SelKey >= PropKeyCount(c, g_SelKeyProp)) return -2;
    if(g_SelKeyProp == 0) return c.kPos[g_SelKey].easeType;
    if(g_SelKeyProp == 1) return c.kScale[g_SelKey].easeType;
    if(g_SelKeyProp == 2) return c.kRot[g_SelKey].easeType;
    return c.kOp[g_SelKey].easeType;
}

// ponytail: AE diamond semantics — the row button adds a key here, or removes the one here
static float ClipLocalNow(const TimelineItem& c){
    return clampf((g_PlayTime - c.startTime) / std::max(0.1f, c.speed), 0.0f, c.duration);
}
static bool KeyAtPlayhead(const TimelineItem& c, int bit){
    float lt = ClipLocalNow(c);
    if(bit == KP_POS) return KeyIndexAt(c.kPos, lt, 0.06f) >= 0;
    if(bit == KP_SCALE) return KeyIndexAt(c.kScale, lt, 0.06f) >= 0;
    if(bit == KP_ROT) return KeyIndexAt(c.kRot, lt, 0.06f) >= 0;
    return KeyIndexAt(c.kOp, lt, 0.06f) >= 0;
}
static void ToggleKeyAtPlayhead(TimelineItem& c, int bit){
    float lt = ClipLocalNow(c);
    Camera ec = EvaluateClipTransform(c, lt);
    if(bit == KP_POS){
        int idx = KeyIndexAt(c.kPos, lt, 0.06f);
        if(idx >= 0) c.kPos.erase(c.kPos.begin() + idx);
        else UpsertPosKey(c, lt, ec.px, ec.py);
    }else if(bit == KP_SCALE){
        int idx = KeyIndexAt(c.kScale, lt, 0.06f);
        if(idx >= 0) c.kScale.erase(c.kScale.begin() + idx);
        else UpsertKey1D(c.kScale, lt, ec.zoom, c.duration);
    }else if(bit == KP_ROT){
        int idx = KeyIndexAt(c.kRot, lt, 0.06f);
        if(idx >= 0) c.kRot.erase(c.kRot.begin() + idx);
        else UpsertKey1D(c.kRot, lt, ec.rot, c.duration);
    }else{
        int idx = KeyIndexAt(c.kOp, lt, 0.06f);
        if(idx >= 0) c.kOp.erase(c.kOp.begin() + idx);
        else UpsertKey1D(c.kOp, lt, EvaluateClipOpacity(c, lt), c.duration);
    }
    RefreshKenBurns(c);
}

// ponytail: graph presets stamp easing onto props that have keys (creates all four if none)
static void EnsurePropKeys(TimelineItem& c){
    if(c.kPos.empty() && c.kScale.empty() && c.kRot.empty() && c.kOp.empty()){
        Key2D a; a.time = 0.0f; a.x = c.cam.px; a.y = c.cam.py;
        Key2D b; b.time = c.duration; b.x = c.cam.px; b.y = c.cam.py;
        c.kPos.push_back(a); c.kPos.push_back(b);
        Key1D a1; a1.time = 0.0f; a1.value = c.cam.zoom;
        Key1D b1; b1.time = c.duration; b1.value = c.cam.zoom;
        c.kScale.push_back(a1); c.kScale.push_back(b1);
        Key1D a2; a2.time = 0.0f; a2.value = c.cam.rot;
        Key1D b2; b2.time = c.duration; b2.value = c.cam.rot;
        c.kRot.push_back(a2); c.kRot.push_back(b2);
        Key1D a3; a3.time = 0.0f; a3.value = c.textAlpha;
        Key1D b3; b3.time = c.duration; b3.value = c.textAlpha;
        c.kOp.push_back(a3); c.kOp.push_back(b3);
    }
}
static void ApplyEaseAll(TimelineItem& c, int easeType, const float* bez){
    // A selected key gets the curve alone; with no key selected the whole clip does (old behavior)
    if(g_SelKey >= 0 && g_SelKeyProp >= 0 && g_SelKeyProp <= 3 && g_SelKey < PropKeyCount(c, g_SelKeyProp)){
        if(g_SelKeyProp == 0){ auto& k = c.kPos[g_SelKey]; k.easeType = easeType; memcpy(k.bezCP, bez, sizeof k.bezCP); }
        else if(g_SelKeyProp == 1){ auto& k = c.kScale[g_SelKey]; k.easeType = easeType; memcpy(k.bezCP, bez, sizeof k.bezCP); }
        else if(g_SelKeyProp == 2){ auto& k = c.kRot[g_SelKey]; k.easeType = easeType; memcpy(k.bezCP, bez, sizeof k.bezCP); }
        else{ auto& k = c.kOp[g_SelKey]; k.easeType = easeType; memcpy(k.bezCP, bez, sizeof k.bezCP); }
        RefreshKenBurns(c);
        return;
    }
    EnsurePropKeys(c);
    for(auto& k : c.kPos){ k.easeType = easeType; memcpy(k.bezCP, bez, sizeof k.bezCP); }
    for(auto& k : c.kScale){ k.easeType = easeType; memcpy(k.bezCP, bez, sizeof k.bezCP); }
    for(auto& k : c.kRot){ k.easeType = easeType; memcpy(k.bezCP, bez, sizeof k.bezCP); }
    for(auto& k : c.kOp){ k.easeType = easeType; memcpy(k.bezCP, bez, sizeof k.bezCP); }
    RefreshKenBurns(c);
}

static int FindKeyframeIndexAt(const TimelineItem& c, int prop, float localTime, float threshold = 0.08f){
    for(int i = 0; i < PropKeyCount(c, prop); i++)
        if(fabsf(PropKeyTime(c, prop, i) - localTime) <= threshold) return i;
    return -1;
}

// ponytail: AE-style key jump (U / Shift+U) across all props of the selected clip
static void JumpKeyframe(int dir){
    if(g_SelClip < 0 || g_SelClip >= (int)g_Clips.size()) return;
    TimelineItem& c = g_Clips[g_SelClip];
    float spd = std::max(0.1f, c.speed);
    float best = (dir > 0) ? 1e30f : -1e30f;
    int bestP = -1, bestI = -1;
    for(int p = 0; p < 4; p++){
        for(int i = 0; i < PropKeyCount(c, p); i++){
            float gt = c.startTime + PropKeyTime(c, p, i) * spd;
            if(dir > 0 && gt > g_PlayTime + 1e-4f && gt < best){ best = gt; bestP = p; bestI = i; }
            if(dir < 0 && gt < g_PlayTime - 1e-4f && gt > best){ best = gt; bestP = p; bestI = i; }
        }
    }
    if(bestI >= 0){
        g_PlayTime = SnapToFrame(best, g_FPS);
        g_SelKeyProp = bestP;
        g_SelKey = bestI;
        g_Dirty = true;
    }
}

// ponytail: magnet scrub snaps to nearby keyframes (any clip, any prop), else plain frame snap
static float SnapPlayheadToKeys(float t){
    float win = 1.5f / std::max(1.0f, g_FPS);
    float bestT = t, bestD = win;
    for(auto& c : g_Clips){
        float spd = std::max(0.1f, c.speed);
        for(int p = 0; p < 4; p++){
            for(int i = 0; i < PropKeyCount(c, p); i++){
                float gt = c.startTime + PropKeyTime(c, p, i) * spd;
                float d = fabsf(gt - t);
                if(d < bestD){ bestD = d; bestT = gt; }
            }
        }
    }
    for(float m : g_Markers){ float d = fabsf(m - t); if(d < bestD){ bestD = d; bestT = m; } }
    return SnapToFrame(bestT, g_FPS);
}

// ponytail: timeline markers + work area. Markers are intentionally outside undo (they're navigation, not content).
static void AddMarkerAt(float t){
    t = SnapToFrame(t, g_FPS);
    for(float m : g_Markers) if(fabsf(m - t) < 0.5f / std::max(1.0f, g_FPS)) return; // no dupes
    g_Markers.push_back(t);
    std::sort(g_Markers.begin(), g_Markers.end());
    g_Dirty = true;
}
static void DeleteMarkerAt(float t){
    float win = 1.5f / std::max(1.0f, g_FPS);
    for(size_t i = 0; i < g_Markers.size(); i++)
        if(fabsf(g_Markers[i] - t) < win){ g_Markers.erase(g_Markers.begin() + i); g_Dirty = true; return; }
}
static void JumpMarker(int dir){
    if(g_Markers.empty()) return;
    float best = (dir > 0) ? 1e30f : -1e30f;
    bool found = false;
    for(float m : g_Markers){
        if(dir > 0 && m > g_PlayTime + 1e-4f && m < best){ best = m; found = true; }
        if(dir < 0 && m < g_PlayTime - 1e-4f && m > best){ best = m; found = true; }
    }
    if(found){ g_PlayTime = best; g_Dirty = true; }
}
static bool WorkAreaActive(){ return g_WorkIn >= 0.0f && g_WorkOut > g_WorkIn; }

static void SplitClipAtPlayhead(){
    if(g_SelClip<0||g_SelClip>=(int)g_Clips.size())return;
    float cs=g_Clips[g_SelClip].startTime, cd=ClipDur(g_SelClip);
    float local=g_PlayTime-cs;
    if(local<=0.05f||local>=cd-0.05f)return;
    PushUndo(); // after the no-op guard: a rejected split must not push a junk snapshot or wipe redo
    TimelineItem left=g_Clips[g_SelClip];
    TimelineItem right=g_Clips[g_SelClip];
    float spd=std::max(0.1f,left.speed);
    left.duration=local/spd;
    right.startTime=cs+local;
    right.duration=(cd-local)/spd;
    right.srcOff=left.srcOff+local/spd; // media offset at the cut, or the right half restarts the footage
    left.kPos.clear(); right.kPos.clear();
    left.kScale.clear(); right.kScale.clear();
    left.kRot.clear(); right.kRot.clear();
    left.kOp.clear(); right.kOp.clear();
    SplitKeyList(g_Clips[g_SelClip].kPos, local, left.kPos, right.kPos);
    SplitKeyList(g_Clips[g_SelClip].kScale, local, left.kScale, right.kScale);
    SplitKeyList(g_Clips[g_SelClip].kRot, local, left.kRot, right.kRot);
    SplitKeyList(g_Clips[g_SelClip].kOp, local, left.kOp, right.kOp);
    RefreshKenBurns(left);
    RefreshKenBurns(right);
    g_Clips[g_SelClip]=left;
    g_Clips.insert(g_Clips.begin()+g_SelClip+1,right);
    g_SelClip=g_SelClip+1;
    g_Dirty=true;
}

static void RippleDelete(){ // delete selection and close the gap on each affected track (Shift+Del)
    std::vector<int> doomed;
    if(g_SelMulti.size() > 1) doomed = g_SelMulti;
    else if(g_SelClip >= 0 && g_SelClip < (int)g_Clips.size()) doomed.push_back(g_SelClip);
    else return;
    struct Win{ int track; float s, e; };
    std::vector<Win> wins;
    for(int idx : doomed){
        if(idx < 0 || idx >= (int)g_Clips.size()) continue;
        const auto& c = g_Clips[idx];
        wins.push_back({c.track, c.startTime, c.startTime + c.duration * std::max(0.1f, c.speed)});
    }
    if(wins.empty()) return;
    PushUndo();
    std::sort(doomed.begin(), doomed.end());
    for(int i = (int)doomed.size() - 1; i >= 0; i--){
        int idx = doomed[i];
        if(idx >= 0 && idx < (int)g_Clips.size()) g_Clips.erase(g_Clips.begin() + idx);
    }
    for(auto& c : g_Clips){ // close each deleted window from the survivors' original coordinates
        float shift = 0.0f;
        for(auto& w : wins) if(w.track == c.track && w.e <= c.startTime + 1e-4f) shift += w.e - w.s;
        c.startTime -= shift;
    }
    g_SelClip = -1; g_SelMulti.clear(); g_SelKey = -1; g_SelKeyProp = -1;
    g_Dirty = true;
}

static void DeleteSelectedClip(){
    // ponytail: marquee batch — Delete removes every box-selected clip in one undo
    if(g_SelMulti.size() > 1){
        PushUndo();
        std::sort(g_SelMulti.begin(), g_SelMulti.end());
        for(int i = (int)g_SelMulti.size() - 1; i >= 0; i--){
            int idx = g_SelMulti[i];
            if(idx >= 0 && idx < (int)g_Clips.size()) g_Clips.erase(g_Clips.begin() + idx);
        }
        g_SelClip = -1; g_SelMulti.clear();
        g_Dirty = true;
        return;
    }
    if(g_SelClip<0||g_SelClip>=(int)g_Clips.size())return;
    PushUndo();
    g_Clips.erase(g_Clips.begin()+g_SelClip);
    if(g_SelClip>=(int)g_Clips.size())g_SelClip=(int)g_Clips.size()-1;
    g_Dirty=true;
}

static void AddNewTextLayer(){
    PushUndo();
    TimelineItem ti;
    ti.type = ITEM_TEXT;
    ti.startTime = g_PlayTime;
    ti.duration = 1.0f; // Default 1.0s duration
    ti.fontSize = 72.0f;
    ti.textColor[0] = 1.0f; ti.textColor[1] = 1.0f; ti.textColor[2] = 1.0f;
    ti.textAlpha = 1.0f;
    snprintf(ti.textContent, sizeof ti.textContent, "Text Layer %d", (int)g_Clips.size() + 1);

    // After Effects model: 1 layer contains only 1 object
    int targetTrack = 0;
    for(int tr = 0; tr < 256; tr++){
        bool occupied = false;
        for(const auto& item : g_Clips){
            if(item.track == tr){
                occupied = true;
                break;
            }
        }
        if(!occupied){
            targetTrack = tr;
            break;
        }
    }
    ti.track = targetTrack;
    EnsureTrackSize(targetTrack);
    g_Clips.push_back(ti);
    g_SelClip = (int)g_Clips.size() - 1;
    g_Dirty = true;
}

// ============ textures / sampling ============
static void UploadTex(ImageData&im){
    if(!im.tex&&im.px){
        glGenTextures(1,&im.tex);
        glBindTexture(GL_TEXTURE_2D,im.tex);
        glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR);
        glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);
        glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);
        glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);
        glPixelStorei(GL_UNPACK_ALIGNMENT,4);
        glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA8,im.w,im.h,0,GL_RGBA,GL_UNSIGNED_BYTE,im.px);
    }
}

// Zero-allocation FX implementations
static void FX_Flip(unsigned char*b,int w,int h,int mode){
    EnsureScratch((size_t)w*h*4);
    memcpy(s_FxScratch1.data(),b,(size_t)w*h*4);
    for(int y=0;y<h;y++)for(int x=0;x<w;x++){
        int sx=mode==0?w-1-x:x;int sy=mode==1?h-1-y:y;
        int o=(y*w+x)*4,s=(sy*w+sx)*4;b[o]=s_FxScratch1[s];b[o+1]=s_FxScratch1[s+1];b[o+2]=s_FxScratch1[s+2];b[o+3]=s_FxScratch1[s+3];
    }
}
static void FX_Mosaic(unsigned char*b,int w,int h,int bs){
    bs=std::max(1,bs);
    EnsureScratch((size_t)w*h*4);
    memcpy(s_FxScratch1.data(),b,(size_t)w*h*4);
    for(int y=0;y<h;y+=bs)for(int x=0;x<w;x+=bs){
        int r=0,g=0,bl=0,n=0;int xe=std::min(w,x+bs),ye=std::min(h,y+bs);
        for(int yy=y;yy<ye;yy++)for(int xx=x;xx<xe;xx++){int o=(yy*w+xx)*4;r+=s_FxScratch1[o];g+=s_FxScratch1[o+1];bl+=s_FxScratch1[o+2];n++;}
        if(n){r/=n;g/=n;bl/=n;for(int yy=y;yy<ye;yy++)for(int xx=x;xx<xe;xx++){int o=(yy*w+xx)*4;b[o]=r;b[o+1]=g;b[o+2]=bl;}}
    }
}
static void FX_Posterize(unsigned char*b,int w,int h,float levels){
    int l=std::max((int)levels,2);if(l>64)l=64;
    for(int y=0;y<h;y++)for(int x=0;x<w;x++){
        int o=(y*w+x)*4;
        b[o]=(unsigned char)((b[o]*l/256)*256/l);
        b[o+1]=(unsigned char)((b[o+1]*l/256)*256/l);
        b[o+2]=(unsigned char)((b[o+2]*l/256)*256/l);
    }
}
static void FX_Grid(unsigned char*b,int w,int h,float spacing,float thickness,float r,float g,float bl,float a){
    int sp=std::max((int)spacing,2),th=std::max((int)thickness,1);
    for(int y=0;y<h;y++)for(int x=0;x<w;x++){
        if(x%sp<th||y%sp<th){
            int o=(y*w+x)*4;
            // ponytail: snapshot channels first — the old code fed blended red into green/blue
            unsigned char oR=b[o],oG=b[o+1],oB=b[o+2];
            b[o]=(unsigned char)(oR*(1-a)+r*255*a);b[o+1]=(unsigned char)(oG*(1-a)+g*255*a);b[o+2]=(unsigned char)(oB*(1-a)+bl*255*a);
        }
    }
}
static void FX_Crop(unsigned char*b,int w,int h,float l,float r,float t,float bm){
    l=clampf(l,0,0.49f);r=clampf(r,0,0.49f);t=clampf(t,0,0.49f);bm=clampf(bm,0,0.49f);
    float fw=1.0f-l-r,fh=1.0f-t-bm;
    EnsureScratch((size_t)w*h*4);
    memcpy(s_FxScratch1.data(),b,(size_t)w*h*4);
    for(int y=0;y<h;y++){
        int syi=(int)((t+y*((float)fh/h))*h);if(syi>=h)syi=h-1;if(syi<0)syi=0;
        for(int x=0;x<w;x++){
            int sxi=(int)((l+x*((float)fw/w))*w);if(sxi>=w)sxi=w-1;if(sxi<0)sxi=0;
            int o=(y*w+x)*4,s=(syi*w+sxi)*4;
            b[o]=s_FxScratch1[s];b[o+1]=s_FxScratch1[s+1];b[o+2]=s_FxScratch1[s+2];b[o+3]=s_FxScratch1[s+3];
        }
    }
}
static void FX_ColorMatrix(unsigned char*b,int w,int h,float r,float g,float bl,float amt){
    amt=clampf(amt,0,1);
    for(int y=0;y<h;y++)for(int x=0;x<w;x++){
        int o=(y*w+x)*4;
        b[o]=(unsigned char)clampf(b[o]*(1-amt)+r*255*amt,0,255);
        b[o+1]=(unsigned char)clampf(b[o+1]*(1-amt)+g*255*amt,0,255);
        b[o+2]=(unsigned char)clampf(b[o+2]*(1-amt)+bl*255*amt,0,255);
    }
}
static void FX_Outline(unsigned char*b,int w,int h,int th,float r,float g,float bl){
    r=clampf(r,0,1);g=clampf(g,0,1);bl=clampf(bl,0,1); // generic Amount slider can push p[1] to 10: clamp, don't wrap
    th=std::clamp(th,1,20);
    EnsureScratch((size_t)w*h*4);
    memcpy(s_FxScratch1.data(),b,(size_t)w*h*4);
    for(int y=th;y<h-th;y++)for(int x=th;x<w-th;x++){
        int o=(y*w+x)*4;
        bool edge=false;
        for(int dy=-th;dy<=th&&!edge;dy++)for(int dx=-th;dx<=th&&!edge;dx++){
            if(dx==0&&dy==0)continue;
            float l0=s_FxScratch1[o]*0.299f+s_FxScratch1[o+1]*0.587f+s_FxScratch1[o+2]*0.114f;
            int s=((y+dy)*w+x+dx)*4;
            float l1=s_FxScratch1[s]*0.299f+s_FxScratch1[s+1]*0.587f+s_FxScratch1[s+2]*0.114f;
            if(fabsf(l0-l1)>64.0f)edge=true;
        }
        if(edge){b[o]=(unsigned char)(r*255);b[o+1]=(unsigned char)(g*255);b[o+2]=(unsigned char)(bl*255);}
    }
}
static void FX_Shadow(unsigned char*b,int w,int h,int ox,int oy,float a){
    a=clampf(a,0,1);
    if(a<=0.0f||(ox==0&&oy==0))return;
    EnsureScratch((size_t)w*h*4);
    memcpy(s_FxScratch1.data(),b,(size_t)w*h*4);
    for(int y=0;y<h;y++)for(int x=0;x<w;x++){
        int sx=x-ox, sy=y-oy;
        if(sx<0||sx>=w||sy<0||sy>=h)continue; // negative offsets read before the buffer without this
        int o=(y*w+x)*4,s=(sy*w+sx)*4;
        float l0=s_FxScratch1[s]*0.299f+s_FxScratch1[s+1]*0.587f+s_FxScratch1[s+2]*0.114f;
        if(l0<100.0f){unsigned char oR=b[o],oG=b[o+1],oB=b[o+2];b[o]=(unsigned char)(oR*(1-a));b[o+1]=(unsigned char)(oG*(1-a));b[o+2]=(unsigned char)(oB*(1-a));}
    }
}
static void FX_Gradient(unsigned char*b,int w,int h,float r1,float g1,float bl1,float r2,float g2,float bl2,float ang,float amt){
    ang=ang*3.14159265f/180.0f;amt=clampf(amt,0,1);
    float ca=cosf(ang),sa=sinf(ang);
    for(int y=0;y<h;y++)for(int x=0;x<w;x++){
        float nx=(x-(float)w*0.5f)/w,ny=(y-(float)h*0.5f)/h;
        float d=nx*ca+ny*sa;d=(d*0.5f+0.5f);
        float r=r1+(r2-r1)*d,g=g1+(g2-g1)*d,bl=bl1+(bl2-bl1)*d;
        int o=(y*w+x)*4;
        b[o]=(unsigned char)clampf(b[o]*(1-amt)+r*255*amt,0,255);
        b[o+1]=(unsigned char)clampf(b[o+1]*(1-amt)+g*255*amt,0,255);
        b[o+2]=(unsigned char)clampf(b[o+2]*(1-amt)+bl*255*amt,0,255);
    }
}
static void FX_Halftone(unsigned char*b,int w,int h,float dot){
    dot=std::max(dot,1.0f);
    for(int y=0;y<h;y++)for(int x=0;x<w;x++){
        int o=(y*w+x)*4;
        float l=b[o]*0.299f+b[o+1]*0.587f+b[o+2]*0.114f;
        int id=(int)(x/dot)+(int)(y/dot)*131;
        float rnd=(float)((id*37)&255)/255.0f;
        unsigned char v=l>rnd*255.0f?255:0;
        b[o]=b[o+1]=b[o+2]=v;
    }
}
static void FX_Chromatic(unsigned char*b,int w,int h,int off){
    EnsureScratch((size_t)w*h*4);
    memcpy(s_FxScratch1.data(),b,(size_t)w*h*4);
    for(int y=0;y<h;y++)for(int x=0;x<w;x++){
        int o=(y*w+x)*4;
        int rxo=clampf(x+off,0,w-1),rxs=clampf(x-off,0,w-1);
        int rs=(y*w+rxo)*4,gs=(y*w+x)*4,bs=(y*w+rxs)*4;
        b[o]=s_FxScratch1[rs];b[o+1]=s_FxScratch1[gs+1];b[o+2]=s_FxScratch1[bs+2];
    }
}
static void FX_Ghost(unsigned char*b,int w,int h,float shift){
    EnsureScratch((size_t)w*h*4);
    memcpy(s_FxScratch1.data(),b,(size_t)w*h*4);
    int sx=(int)(shift*w);
    for(int y=0;y<h;y++)for(int x=0;x<w;x++){
        int o=(y*w+x)*4;
        int gx=clampf(x-sx,0,w-1);int gs=(y*w+gx)*4;
        float gv=s_FxScratch1[gs]*0.299f+s_FxScratch1[gs+1]*0.587f+s_FxScratch1[gs+2]*0.114f;
        float alpha=(gv/255.0f)*0.6f;
        unsigned char oR=b[o],oG=b[o+1],oB=b[o+2];
        b[o]=(unsigned char)(oR*(1-alpha)+255*alpha);
        b[o+1]=(unsigned char)(oG*(1-alpha)+255*alpha);
        b[o+2]=(unsigned char)(oB*(1-alpha)+255*alpha);
    }
}
static void FX_Wind(unsigned char*b,int w,int h,float strength,int dir){
    EnsureScratch((size_t)w*h*4);
    memcpy(s_FxScratch1.data(),b,(size_t)w*h*4);
    int sh=(int)(strength*w);if(dir<0)sh=-sh;
    for(int y=0;y<h;y++)for(int x=0;x<w;x++){
        int sx=clampf(x+sh,0,w-1);int s=(y*w+sx)*4;int o=(y*w+x)*4;
        b[o]=s_FxScratch1[s];b[o+1]=s_FxScratch1[s+1];b[o+2]=s_FxScratch1[s+2];
    }
}
static void FX_LensDistort(unsigned char*b,int w,int h,float k1,float k2){
    EnsureScratch((size_t)w*h*4);
    memcpy(s_FxScratch1.data(),b,(size_t)w*h*4);
    float cx=w*0.5f,cy=h*0.5f;
    float rmax=sqrtf(cx*cx+cy*cy);
    for(int y=0;y<h;y++)for(int x=0;x<w;x++){
        float dx=(x-cx)/rmax,dy=(y-cy)/rmax;
        float r2=dx*dx+dy*dy;
        float k=r2*k1+r2*r2*k2;
        int sx=(int)(x+dx*k*rmax),sy=(int)(y+dy*k*rmax);
        sx=clampf(sx,0,w-1);sy=clampf(sy,0,h-1);
        int o=(y*w+x)*4,s=(sy*w+sx)*4;
        b[o]=s_FxScratch1[s];b[o+1]=s_FxScratch1[s+1];b[o+2]=s_FxScratch1[s+2];
    }
}

// sample image with bilinear filtering
static void Sample(const unsigned char*src,int sw,int sh,float x,float y,unsigned char out[3]){
    if(src==nullptr){out[0]=out[1]=out[2]=0;return;}
    x=clampf(x,0.0f,sw-1.0001f);y=clampf(y,0.0f,sh-1.0001f);
    int x0=(int)x,y0=(int)y;int x1=x0+1,y1=y0+1;
    if(x1>=sw)x1=sw-1;
    if(y1>=sh)y1=sh-1;
    float fx=x-x0,fy=y-y0;
    const unsigned char*p00=src+(y0*sw+x0)*4,*p10=src+(y0*sw+x1)*4;
    const unsigned char*p01=src+(y1*sw+x0)*4,*p11=src+(y1*sw+x1)*4;
    for(int c=0;c<3;c++){
        float v=(p00[c]*(1-fx)+p10[c]*fx)*(1-fy)+(p01[c]*(1-fx)+p11[c]*fx)*fy;
        out[c]=(unsigned char)v;
    }
}

// ponytail: shared by both warp paths — identical ops to the old inline grade block
static inline void GradePixel(unsigned char col[3], float br, float ct, float sat){
    for(int k=0;k<3;k++){
        float val=col[k]/255.0f;
        val=(val-0.5f)*ct+0.5f+br;
        val=clampf(val,0,1);
        col[k]=(unsigned char)(val*255);
    }
    float lum=col[0]*0.299f+col[1]*0.587f+col[2]*0.114f;
    col[0]=(unsigned char)clampf(lum+(col[0]-lum)*sat,0,255);
    col[1]=(unsigned char)clampf(lum+(col[1]-lum)*sat,0,255);
    col[2]=(unsigned char)clampf(lum+(col[2]-lum)*sat,0,255);
}

// ponytail: axis-aligned warp maps — same recurrence as the general loop, so bit-identical output
static std::vector<int> s_WarpX0, s_WarpY0;
static std::vector<float> s_WarpXf, s_WarpYf;
static void WarpMapFill(int n, float init, float step, float maxV, std::vector<int>& m0, std::vector<float>& mf){
    if((int)m0.size() < n){ m0.resize(n); mf.resize(n); }
    float v = init;
    for(int i = 0; i < n; i++, v += step){
        if(v < 0.0f || v >= maxV){ m0[i] = -1; mf[i] = 0.0f; continue; }
        float c = clampf(v, 0.0f, maxV - 1.0001f);
        m0[i] = (int)c; mf[i] = c - m0[i];
    }
}

// rasterize text into pixel buffer via GDI with dynamic TrueType font support and Kinetic Motion Animator
static void DrawTextToBuffer(unsigned char*b,int w,int h,const char*txt,int fsize,int cx,int cy,unsigned char cr,unsigned char cg,unsigned char cb,float alpha,int fontIdx=0,const Camera*cam=nullptr,const TextAnimParams*anim=nullptr,float localTime=0.0f,float clipDuration=5.0f){
    if(!txt||!txt[0]||alpha<=0.0f)return;
    
    char animTxt[512] = {0};
    strncpy(animTxt, txt, sizeof(animTxt) - 1);

    float effectiveSize = (float)fsize;
    float effectiveAlpha = alpha;
    float offX = 0.0f, offY = 0.0f;

    if(anim && anim->animType != TEXT_ANIM_NONE){
        float inDur = std::max(0.05f, anim->inDur);
        float outDur = std::max(0.05f, anim->outDur);
        float t = localTime;
        float d = clipDuration;

        float u = clampf(t / inDur, 0.0f, 1.0f);
        float v = (t > d - outDur) ? clampf((d - t) / outDur, 0.0f, 1.0f) : 1.0f;

        float easeU = u;
        if(anim->easeType >= 0 && anim->easeType < g_EaseCount){
            easeU = SolveBezierY(u, g_EasePresets[anim->easeType].defaultBez);
        }

        switch(anim->animType){
        case TEXT_ANIM_TYPEWRITER:{
            int len = (int)strlen(txt);
            int visibleChars = clampf((int)((float)len * u), 0, len);
            strncpy(animTxt, txt, visibleChars);
            animTxt[visibleChars] = 0;
            if(u < 0.99f && fmodf(t * 5.0f, 1.0f) < 0.5f){
                strncat(animTxt, "_", sizeof(animTxt) - strlen(animTxt) - 1);
            }
            effectiveAlpha *= v;
            break;
        }
        case TEXT_ANIM_POP_BOUNCE:{
            float spring = 1.0f;
            if(u < 1.0f){
                spring = 0.2f + 1.25f * easeU + 0.25f * sinf(u * 3.14159265f * 2.5f) * (1.0f - u);
            }
            effectiveSize *= spring * v;
            effectiveAlpha *= clampf(u * 2.0f, 0.0f, 1.0f) * v;
            break;
        }
        case TEXT_ANIM_SLIDE_UP:{
            offY = -(1.0f - easeU) * 80.0f + (1.0f - v) * 50.0f;
            effectiveAlpha *= easeU * v;
            break;
        }
        case TEXT_ANIM_SLIDE_LEFT:{
            offX = -(1.0f - easeU) * 140.0f - (1.0f - v) * 80.0f;
            effectiveAlpha *= easeU * v;
            break;
        }
        case TEXT_ANIM_TRACKING_EXPAND:{
            effectiveSize *= (0.7f + 0.3f * easeU);
            effectiveAlpha *= easeU * v;
            break;
        }
        case TEXT_ANIM_FADE_RISE:{
            offY = -(1.0f - easeU) * 35.0f;
            effectiveAlpha *= (easeU * easeU) * v;
            break;
        }
        case TEXT_ANIM_NEON_PULSE:{
            float pulse = 0.75f + 0.25f * sinf(t * 8.0f);
            effectiveAlpha *= easeU * v * pulse;
            break;
        }
        case TEXT_ANIM_RGB_GLITCH:{
            if(u < 0.99f){
                int gstep=(int)floorf(t*24.0f); // deterministic: rand() repainted differently on every mouse move
                float gh1=sinf((float)gstep*12.9898f)*43758.5453f; gh1-=floorf(gh1);
                float gh2=sinf((float)gstep*78.233f)*12543.1234f; gh2-=floorf(gh2);
                offX = (gh1*11.0f - 5.0f) * (1.0f - u);
                offY = (gh2*7.0f - 3.0f) * (1.0f - u);
            }
            effectiveAlpha *= easeU * v;
            break;
        }
        case TEXT_ANIM_3D_FLIP:{
            float flip = sinf(easeU * 3.14159265f * 0.5f);
            effectiveSize *= std::max(0.05f, flip);
            offY = -(1.0f - flip) * 40.0f;
            effectiveAlpha *= easeU * v;
            break;
        }
        case TEXT_ANIM_WAVE_JITTER:{
            offY = sinf(t * 6.0f) * 10.0f;
            effectiveAlpha *= easeU * v;
            break;
        }
        default:
            effectiveAlpha *= v;
            break;
        }

        if(anim->loopIdle && u >= 0.99f && v >= 0.99f){
            offY += sinf(t * 4.0f * anim->idleSpeed) * 6.0f;
        }
    }

    if(effectiveAlpha <= 0.005f) return;
    if(cam) effectiveSize *= cam->zoom;

    int fs = (int)effectiveSize;
    if(fs <= 2) return;

    int tw = w, th = std::max(32, fs * 3);
    if(th <= 0 || tw <= 0) return;

    // ponytail: skip GDI re-raster when the white glyph is unchanged (typewriter variegates animTxt).
    // cam.zoom is baked into fs; rotation/offsets/color are all applied at blit time, so the raster is cacheable.
    bool cacheable = strcmp(animTxt, txt) == 0;
    std::string ckey;
    HDC dc = nullptr; HBITMAP bmp = nullptr; HFONT ft = nullptr;
    unsigned char* px = nullptr;
    if(cacheable){
        ckey = std::string(txt) + "|" + std::to_string(fs) + "|" + std::to_string(fontIdx) + "|" + std::to_string(w);
        auto it = s_TextCache.find(ckey);
        if(it != s_TextCache.end()){ th = it->second.th; px = it->second.px.data(); }
    }
    if(!px){
        BITMAPINFO bi={0};bi.bmiHeader.biSize=sizeof(bi.bmiHeader);bi.bmiHeader.biWidth=tw;bi.bmiHeader.biHeight=-th;bi.bmiHeader.biPlanes=1;bi.bmiHeader.biBitCount=32;
        dc=CreateCompatibleDC(NULL);
        bmp=CreateDIBSection(dc,&bi,DIB_RGB_COLORS,(void**)&px,NULL,0);
        SelectObject(dc,bmp);
        RECT rc={0,0,tw,th};
        FillRect(dc,&rc,(HBRUSH)GetStockObject(BLACK_BRUSH));

        std::string useFace = "Segoe UI";
        int weight = FW_BOLD;
        BOOL italic = FALSE;

        if(fontIdx >= 0 && fontIdx < (int)g_AvailableFonts.size()){
            useFace = g_AvailableFonts[fontIdx].gdiFamilyName;
            weight = g_AvailableFonts[fontIdx].weight;
            italic = g_AvailableFonts[fontIdx].italic ? TRUE : FALSE;
        }

        ft=CreateFontA(fs, 0, 0, 0, weight, italic, FALSE, FALSE, DEFAULT_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS, CLEARTYPE_QUALITY, DEFAULT_PITCH, useFace.c_str());
        SelectObject(dc,ft);
        SetBkMode(dc,TRANSPARENT);
        SetTextColor(dc,RGB(255,255,255));
        DrawTextA(dc,animTxt,-1,&rc,DT_CENTER|DT_VCENTER|DT_SINGLELINE|DT_NOCLIP);
        if(cacheable){
            if(s_TextCache.size() >= 8) s_TextCache.clear(); // ponytail: hard cap, clear-all beats eviction logic
            s_TextCache[ckey] = { th, std::vector<unsigned char>(px, px + (size_t)tw*th*4) };
        }
    }

    int finalCX = cx + (int)offX, finalCY = cy + (int)offY;
    float rotR = 0.0f;
    if(cam){
        finalCX += (int)(cam->px * w * 0.5f);
        finalCY += (int)(cam->py * h * 0.5f);
        rotR = cam->rot;
    }

    // ponytail: rotate glyph blit around its center (was axis-aligned: rotation did nothing)
    float cosR = cosf(rotR), sinR = sinf(rotR);
    for(int ty=0;ty<th;ty++)for(int tx=0;tx<tw;tx++){
        unsigned char a=px[(ty*tw+tx)*4];
        if(!a)continue;
        float ox = (float)tx - tw*0.5f, oy = (float)ty - th*0.5f;
        int bx = finalCX + (int)(ox * cosR - oy * sinR);
        int by = finalCY + (int)(ox * sinR + oy * cosR);
        if(bx<0||bx>=w||by<0||by>=h)continue;
        float al=(a/255.0f)*effectiveAlpha;
        int o=(by*w+bx)*4;
        b[o]=(unsigned char)clampf(b[o]*(1-al)+cr*al,0,255);
        b[o+1]=(unsigned char)clampf(b[o+1]*(1-al)+cg*al,0,255);
        b[o+2]=(unsigned char)clampf(b[o+2]*(1-al)+cb*al,0,255);
        b[o+3]=(unsigned char)std::min(255, (int)(b[o+3] + a * effectiveAlpha));
    }
    DeleteDC(dc); // must go first: DeleteObject fails on GDI objects still selected into a DC (leaked a DIB+font per uncached raster)
    DeleteObject(ft);DeleteObject(bmp);
}

// ============ Smart Depth Blur (3D Optical Depth of Field) ============
static void ApplySmartDepthBlur(unsigned char* b, int w, int h, const FXParams& fx){
    float maxR = std::clamp(fx.p[0], 0.0f, 40.0f);
    if(maxR < 0.5f) return;

    int mode = (int)fx.p[3]; // UI combo writes p[3]; p[6] was read here so the mode selector was dead
    float focalPlane = std::clamp(fx.p[1], 0.0f, 1.0f);
    float depthRange = std::clamp(fx.p[2] > 0.01f ? fx.p[2] : 0.35f, 0.02f, 1.0f);
    float falloff = std::clamp(fx.p[4] > 0.01f ? fx.p[4] : 0.6f, 0.05f, 2.0f);

    EnsureScratch((size_t)w * h * 4);
    unsigned char* origBuf = s_FxScratch1.data();
    unsigned char* blurBuf = s_FxScratch2.data();
    unsigned char* vBuf = s_FxScratch3.data();
    memcpy(origBuf, b, (size_t)w * h * 4);

    int iR = std::clamp((int)maxR, 1, 35);
    
    // Fast O(1) separable sliding moving-sum blur passes
    // Horizontal pass:
    for(int y = 0; y < h; y++){
        int yw = y * w;
        int rSum = 0, gSum = 0, bSum = 0, aSum = 0, count = 0;
        int initR = std::min(w - 1, iR);
        for(int kx = 0; kx <= initR; kx++){
            int idx = (yw + kx) * 4;
            rSum += origBuf[idx];
            gSum += origBuf[idx+1];
            bSum += origBuf[idx+2];
            aSum += origBuf[idx+3];
            count++;
        }
        for(int x = 0; x < w; x++){
            if(x + iR < w && x > 0){
                int inIdx = (yw + x + iR) * 4;
                rSum += origBuf[inIdx];
                gSum += origBuf[inIdx+1];
                bSum += origBuf[inIdx+2];
                aSum += origBuf[inIdx+3];
                count++;
            }
            if(x - iR - 1 >= 0){
                int outIdx = (yw + x - iR - 1) * 4;
                rSum -= origBuf[outIdx];
                gSum -= origBuf[outIdx+1];
                bSum -= origBuf[outIdx+2];
                aSum -= origBuf[outIdx+3];
                count--;
            }
            int dstIdx = (yw + x) * 4;
            blurBuf[dstIdx]   = (unsigned char)(rSum / count);
            blurBuf[dstIdx+1] = (unsigned char)(gSum / count);
            blurBuf[dstIdx+2] = (unsigned char)(bSum / count);
            blurBuf[dstIdx+3] = (unsigned char)(aSum / count);
        }
    }

    // Vertical pass:
    for(int x = 0; x < w; x++){
        int rSum = 0, gSum = 0, bSum = 0, aSum = 0, count = 0;
        int initR = std::min(h - 1, iR);
        for(int ky = 0; ky <= initR; ky++){
            int idx = (ky * w + x) * 4;
            rSum += blurBuf[idx];
            gSum += blurBuf[idx+1];
            bSum += blurBuf[idx+2];
            aSum += blurBuf[idx+3];
            count++;
        }
        for(int y = 0; y < h; y++){
            if(y + iR < h && y > 0){
                int inIdx = ((y + iR) * w + x) * 4;
                rSum += blurBuf[inIdx];
                gSum += blurBuf[inIdx+1];
                bSum += blurBuf[inIdx+2];
                aSum += blurBuf[inIdx+3];
                count++;
            }
            if(y - iR - 1 >= 0){
                int outIdx = ((y - iR - 1) * w + x) * 4;
                rSum -= blurBuf[outIdx];
                gSum -= blurBuf[outIdx+1];
                bSum -= blurBuf[outIdx+2];
                aSum -= blurBuf[outIdx+3];
                count--;
            }
            int dstIdx = (y * w + x) * 4;
            vBuf[dstIdx]   = (unsigned char)(rSum / count);
            vBuf[dstIdx+1] = (unsigned char)(gSum / count);
            vBuf[dstIdx+2] = (unsigned char)(bSum / count);
            vBuf[dstIdx+3] = (unsigned char)(aSum / count);
        }
    }

    // Blend sharp and blurred buffers based on depth map
    float cx = w * 0.5f, cy = h * 0.5f;
    for(int y = 0; y < h; y++){
        int yw = y * w;
        for(int x = 0; x < w; x++){
            int idx = (yw + x) * 4;
            float m = 0.0f;

            if(mode == 0){ // Multi-Layer Depth Mode
                m = 1.0f;
            }else if(mode == 1){ // Radial / Spherical Bokeh
                float nx = (x - cx) / cx;
                float ny = (y - cy) / cy;
                float dist = sqrtf(nx*nx + ny*ny);
                m = clampf((dist - depthRange) / falloff, 0.0f, 1.0f);
            }else if(mode == 2){ // Tilt-Shift Band
                float ny = fabsf((y - cy) / cy);
                m = clampf((ny - depthRange) / falloff, 0.0f, 1.0f);
            }else if(mode == 3){ // Luminance Depth Map
                float lum = (origBuf[idx]*0.299f + origBuf[idx+1]*0.587f + origBuf[idx+2]*0.114f) / 255.0f;
                float diff = fabsf(lum - focalPlane);
                m = clampf((diff - depthRange) / falloff, 0.0f, 1.0f);
            }

            b[idx]   = (unsigned char)clampf(origBuf[idx]*(1.0f - m) + vBuf[idx]*m, 0.0f, 255.0f);
            b[idx+1] = (unsigned char)clampf(origBuf[idx+1]*(1.0f - m) + vBuf[idx+1]*m, 0.0f, 255.0f);
            b[idx+2] = (unsigned char)clampf(origBuf[idx+2]*(1.0f - m) + vBuf[idx+2]*m, 0.0f, 255.0f);
            b[idx+3] = origBuf[idx+3];
        }
    }
}

// ============ FX pipeline ============
static void ApplyFXPipeline(unsigned char*b,int w,int h,const std::vector<FXParams>&fx,float fxTime=0.0f){
    for(const auto&e:fx){
        if(!e.enabled)continue;
        switch(e.type){
        case FX_RGB_SPLIT:{
            EnsureScratch((size_t)w*h*4);
            memcpy(s_FxScratch1.data(),b,(size_t)w*h*4);
            int off=std::max(1,(int)e.p[0]);
            float ang=e.p[1]*3.14159265f/180.0f; // the Angle slider was accepted and never read: offsets were horizontal-only
            int dx=(int)roundf(cosf(ang)*off), dy=(int)roundf(sinf(ang)*off);
            for(int y=0;y<h;y++)for(int x=0;x<w;x++){
                int o=(y*w+x)*4;
                int rx=std::clamp(x+dx,0,w-1),bx=std::clamp(x-dx,0,w-1);
                int ry=std::clamp(y+dy,0,h-1),by=std::clamp(y-dy,0,h-1);
                b[o]=s_FxScratch1[(ry*w+rx)*4];b[o+2]=s_FxScratch1[(by*w+bx)*4+2];
            }break;}
        case FX_GAUSSIAN_BLUR:{
            // O(1)-per-pixel sliding box passes over PREMULTIPLIED rgba: the old O(w*h*r) 101-tap gather
            // stalled scrubbing at r=50, and raw-RGB averaging haloed dark edges + kept a razor alpha cut.
            // Two box passes ~= gaussian visually; alpha blurs too, then un-premultiplies. Output differs from the old build (wrong-slow -> right-fast).
            int r=std::clamp((int)e.p[0],1,35);
            if(r<1) break;
            EnsureScratch((size_t)w*h*4);
            unsigned char* pm=s_FxScratch1.data();
            for(int i=0;i<w*h*4;i+=4){unsigned char a=b[i+3];pm[i]=(unsigned char)(b[i]*a/255);pm[i+1]=(unsigned char)(b[i+1]*a/255);pm[i+2]=(unsigned char)(b[i+2]*a/255);pm[i+3]=a;}
            unsigned char* hb=s_FxScratch2.data();
            for(int y=0;y<h;y++){
                int yw=y*w, rS=0,gS=0,bS=0,aS=0,cnt=0;
                for(int kx=0;kx<=std::min(w-1,r);kx++){int id=(yw+kx)*4;rS+=pm[id];gS+=pm[id+1];bS+=pm[id+2];aS+=pm[id+3];cnt++;}
                for(int x=0;x<w;x++){
                    if(x+r<w&&x>0){int id=(yw+x+r)*4;rS+=pm[id];gS+=pm[id+1];bS+=pm[id+2];aS+=pm[id+3];cnt++;}
                    if(x-r-1>=0){int id=(yw+x-r-1)*4;rS-=pm[id];gS-=pm[id+1];bS-=pm[id+2];aS-=pm[id+3];cnt--;}
                    int dd=(yw+x)*4;hb[dd]=(unsigned char)(rS/cnt);hb[dd+1]=(unsigned char)(gS/cnt);hb[dd+2]=(unsigned char)(bS/cnt);hb[dd+3]=(unsigned char)(aS/cnt);
                }
            }
            for(int x=0;x<w;x++){
                int rS=0,gS=0,bS=0,aS=0,cnt=0;
                for(int ky=0;ky<=std::min(h-1,r);ky++){int id=(ky*w+x)*4;rS+=hb[id];gS+=hb[id+1];bS+=hb[id+2];aS+=hb[id+3];cnt++;}
                for(int y=0;y<h;y++){
                    if(y+r<h&&y>0){int id=((y+r)*w+x)*4;rS+=hb[id];gS+=hb[id+1];bS+=hb[id+2];aS+=hb[id+3];cnt++;}
                    if(y-r-1>=0){int id=((y-r-1)*w+x)*4;rS-=hb[id];gS-=hb[id+1];bS-=hb[id+2];aS-=hb[id+3];cnt--;}
                    int dd=(y*w+x)*4, a=aS/cnt;
                    if(a>0){b[dd]=(unsigned char)std::min(255,(rS/cnt)*255/a);b[dd+1]=(unsigned char)std::min(255,(gS/cnt)*255/a);b[dd+2]=(unsigned char)std::min(255,(bS/cnt)*255/a);}else b[dd]=b[dd+1]=b[dd+2]=0;
                    b[dd+3]=(unsigned char)a;
                }
            }break;}
        case FX_DIRECTIONAL_BLUR:{
            int n=std::max(1,(int)e.p[0]);float ang=e.p[1]*3.14159265f/180.0f;
            float dx=cosf(ang),dy=sinf(ang);
            EnsureScratch((size_t)w*h*4);
            memcpy(s_FxScratch1.data(),b,(size_t)w*h*4);
            for(int y=0;y<h;y++)for(int x=0;x<w;x++){
                float rr=0,gg=0,bb=0;int cnt=0;
                int st=n>16?(n+8)/16:1; // subsample long smears: 101 taps/px -> <=33, same look, ~3x faster
                for(int i=-n;i<=n;i+=st){
                    int xx=(int)(x+dx*i),yy=(int)(y+dy*i);
                    if(xx<0||xx>=w||yy<0||yy>=h)continue;
                    int o=(yy*w+xx)*4;rr+=s_FxScratch1[o];gg+=s_FxScratch1[o+1];bb+=s_FxScratch1[o+2];cnt++;
                }
                int o=(y*w+x)*4;if(cnt){b[o]=(unsigned char)(rr/cnt);b[o+1]=(unsigned char)(gg/cnt);b[o+2]=(unsigned char)(bb/cnt);}
            }break;}
        case FX_ZOOM_BLUR:{
            int n=std::max(1,(int)e.p[0]);
            EnsureScratch((size_t)w*h*4);
            memcpy(s_FxScratch1.data(),b,(size_t)w*h*4);
            float cx=w*0.5f,cy=h*0.5f;
            for(int y=0;y<h;y++)for(int x=0;x<w;x++){
                float rr=0,gg=0,bb=0;int cnt=0;
                int st=n>16?(n+8)/16:1; // subsample long smears: 101 taps/px -> <=33, same look, ~3x faster
                for(int i=-n;i<=n;i+=st){
                    float f=1.0f+i*0.02f;
                    int xx=(int)(cx+(x-cx)*f),yy=(int)(cy+(y-cy)*f);
                    if(xx<0||xx>=w||yy<0||yy>=h)continue;
                    int o=(yy*w+xx)*4;rr+=s_FxScratch1[o];gg+=s_FxScratch1[o+1];bb+=s_FxScratch1[o+2];cnt++;
                }
                int o=(y*w+x)*4;if(cnt){b[o]=(unsigned char)(rr/cnt);b[o+1]=(unsigned char)(gg/cnt);b[o+2]=(unsigned char)(bb/cnt);}
            }break;}
        case FX_MOSAIC:FX_Mosaic(b,w,h,(int)e.p[0]);break;
        case FX_SHAKE:{
            EnsureScratch((size_t)w*h*4);
            memcpy(s_FxScratch1.data(),b,(size_t)w*h*4);
            float amp=clampf(e.p[1],0.0f,50.0f)/100.0f;
            float speed=clampf(e.p[0],0.1f,10.0f); // old code never read p[0] and used rand(): every repaint jittered differently
            int step=(int)floorf(fxTime*speed*12.0f);
            float h1=sinf((float)step*12.9898f)*43758.5453f; h1-=floorf(h1); // deterministic per-frame hash, no rand state
            float h2=sinf((float)step*78.233f)*12543.1234f; h2-=floorf(h2);
            int sx=(int)(amp*(h1-0.5f)*2.0f*w);
            int sy=(int)(amp*(h2-0.5f)*2.0f*h);
            for(int y=0;y<h;y++)for(int x=0;x<w;x++){
                int xx=clampf(x+sx,0,w-1),yy=clampf(y+sy,0,h-1);
                int o=(y*w+x)*4,s=(yy*w+xx)*4;
                b[o]=s_FxScratch1[s];b[o+1]=s_FxScratch1[s+1];b[o+2]=s_FxScratch1[s+2];
            }break;}
        case FX_VIGNETTE:{
            float amt=clampf(e.p[0]*1.5f,0,3.0f);
            float soft=clampf(e.p[1],0.01f,1.0f);
            float cx=w*0.5f,cy=h*0.5f;float maxd=sqrtf(cx*cx+cy*cy);
            for(int y=0;y<h;y++)for(int x=0;x<w;x++){
                float d=sqrtf((x-cx)*(x-cx)+(y-cy)*(y-cy))/maxd;
                float v=clampf(1.0f-clampf(d/soft,0,1)*amt,0.0f,1.0f); // amt>1 drove v negative: (uchar) of a negative float is UB/a bright ring
                int o=(y*w+x)*4;unsigned char oR=b[o],oG=b[o+1],oB=b[o+2];b[o]=(unsigned char)(oR*v);b[o+1]=(unsigned char)(oG*v);b[o+2]=(unsigned char)(oB*v);
            }break;}
        case FX_INVERT:for(int i=0;i<w*h*4;i+=4){b[i]=255-b[i];b[i+1]=255-b[i+1];b[i+2]=255-b[i+2];}break;
        case FX_SHARPEN:{
            EnsureScratch((size_t)w*h*4);
            memcpy(s_FxScratch1.data(),b,(size_t)w*h*4);
            float amt=clampf(e.p[0],0,1)*1.0f;
            for(int y=1;y<h-1;y++)for(int x=1;x<w-1;x++){
                int o=(y*w+x)*4;
                for(int c=0;c<3;c++){
                    float nv=s_FxScratch1[o+c]*5 - s_FxScratch1[(y*w+x+1)*4+c]-s_FxScratch1[(y*w+x-1)*4+c]-s_FxScratch1[((y+1)*w+x)*4+c]-s_FxScratch1[((y-1)*w+x)*4+c];
                    b[o+c]=(unsigned char)clampf(s_FxScratch1[o+c]+(nv-s_FxScratch1[o+c])*amt,0,255);
                }
            }break;}
        case FX_EDGE_DETECT:{
            EnsureScratch((size_t)w*h*4);
            memcpy(s_FxScratch1.data(),b,(size_t)w*h*4);
            for(int y=1;y<h-1;y++)for(int x=1;x<w-1;x++){
                int o=(y*w+x)*4;
                float gx=0,gy=0;
                int sobel[3][3]={{-1,0,1},{-2,0,2},{-1,0,1}};
                for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++){
                    int s=((y+dy)*w+x+dx)*4;
                    float l=s_FxScratch1[s]*0.299f+s_FxScratch1[s+1]*0.587f+s_FxScratch1[s+2]*0.114f;
                    gx+=l*sobel[dy+1][dx+1];gy+=l*sobel[dx+1][dy+1];
                }
                float m=sqrtf(gx*gx+gy*gy);
                unsigned char v=(unsigned char)clampf(m,0,255);
                b[o]=b[o+1]=b[o+2]=v;
            }break;}
        case FX_THRESHOLD:{
            float t=clampf(e.p[0],0,255);
            for(int i=0;i<w*h*4;i+=4){
                float l=b[i]*0.299f+b[i+1]*0.587f+b[i+2]*0.114f;
                unsigned char v=l>t?255:0;b[i]=b[i+1]=b[i+2]=v;
            }break;}
        case FX_SEPIA:
            for(int i=0;i<w*h*4;i+=4){float r=b[i],g=b[i+1],bl=b[i+2];
                b[i]=(unsigned char)clampf(r*0.393f+g*0.769f+bl*0.189f,0,255);
                b[i+1]=(unsigned char)clampf(r*0.349f+g*0.686f+bl*0.168f,0,255);
                b[i+2]=(unsigned char)clampf(r*0.272f+g*0.534f+bl*0.131f,0,255);}break;
        case FX_GRAYSCALE:
            for(int i=0;i<w*h*4;i+=4){unsigned char v=(unsigned char)(b[i]*0.299f+b[i+1]*0.587f+b[i+2]*0.114f);b[i]=b[i+1]=b[i+2]=v;}break;
        case FX_FLIP:FX_Flip(b,w,h,(int)e.p[0]);break;
        case FX_CROP:FX_Crop(b,w,h,e.p[0],e.p[1],e.p[2],e.p[3]);break;
        case FX_TURBULENCE:{
            float amp=e.p[0];float freq=e.p[1];
            EnsureScratch((size_t)w*h*4);
            memcpy(s_FxScratch1.data(),b,(size_t)w*h*4);
            for(int y=0;y<h;y++)for(int x=0;x<w;x++){
                float n=sinf(x*freq*0.01f)*cosf(y*freq*0.01f);
                int xx=clampf(x+n*amp*w,0,w-1),yy=clampf(y+n*amp*h,0,h-1);
                int o=(y*w+x)*4,s=(yy*w+xx)*4;b[o]=s_FxScratch1[s];b[o+1]=s_FxScratch1[s+1];b[o+2]=s_FxScratch1[s+2];
            }break;}
        case FX_WAVE_WARP:{
            float amp=e.p[1],freq=e.p[0];
            EnsureScratch((size_t)w*h*4);
            memcpy(s_FxScratch1.data(),b,(size_t)w*h*4);
            float phase=fxTime*4.0f; // old code had no phase term: the "warp" was a frozen still
            for(int y=0;y<h;y++)for(int x=0;x<w;x++){
                int xx=clampf(x+sinf(y*freq*0.02f+phase)*amp*w,0,w-1);
                int o=(y*w+x)*4,s=(y*w+xx)*4;b[o]=s_FxScratch1[s];b[o+1]=s_FxScratch1[s+1];b[o+2]=s_FxScratch1[s+2];
            }break;}
        case FX_RIPPLE:{
            float amp=e.p[0];
            EnsureScratch((size_t)w*h*4);
            memcpy(s_FxScratch1.data(),b,(size_t)w*h*4);
            float cx=w*0.5f,cy=h*0.5f;
            for(int y=0;y<h;y++)for(int x=0;x<w;x++){
                float dx=(x-cx),dy=(y-cy);float d=sqrtf(dx*dx+dy*dy);
                float off=sinf(d*0.08f)*amp*w*(d/ (sqrtf(cx*cx+cy*cy)+1));
                int xx=clampf(x+off*(dx/(d+1)),0,w-1),yy=clampf(y+off*(dy/(d+1)),0,h-1);
                int o=(y*w+x)*4,s=(yy*w+xx)*4;b[o]=s_FxScratch1[s];b[o+1]=s_FxScratch1[s+1];b[o+2]=s_FxScratch1[s+2];
            }break;}
        case FX_TWIRL:{
            float amt=e.p[0];
            EnsureScratch((size_t)w*h*4);
            memcpy(s_FxScratch1.data(),b,(size_t)w*h*4);
            float cx=w*0.5f,cy=h*0.5f;
            float rmax=sqrtf(cx*cx+cy*cy);
            for(int y=0;y<h;y++)for(int x=0;x<w;x++){
                float dx=(x-cx),dy=(y-cy);float d=sqrtf(dx*dx+dy*dy);
                float a=amt*(1.0f-d/rmax)*0.5f;
                float cs=cosf(a),sn=sinf(a);
                int xx=clampf(cx+dx*cs-dy*sn,0,w-1),yy=clampf(cy+dx*sn+dy*cs,0,h-1);
                int o=(y*w+x)*4,s=(yy*w+xx)*4;b[o]=s_FxScratch1[s];b[o+1]=s_FxScratch1[s+1];b[o+2]=s_FxScratch1[s+2];
            }break;}
        case FX_FISHEYE:{
            EnsureScratch((size_t)w*h*4);
            memcpy(s_FxScratch1.data(),b,(size_t)w*h*4);
            float cx=w*0.5f,cy=h*0.5f,amt=clampf(e.p[0],-0.98f,1.0f); // amt=-1 => 1/0 exponent, whole frame collapses to center
            float rmax=sqrtf(cx*cx+cy*cy);
            for(int y=0;y<h;y++)for(int x=0;x<w;x++){
                float dx=(x-cx),dy=(y-cy);float d=sqrtf(dx*dx+dy*dy);
                float nd=powf(d/rmax,1.0f/(1.0f+amt))*rmax;
                int xx=clampf(cx+dx*(d>0?nd/d:1),0,w-1),yy=clampf(cy+dy*(d>0?nd/d:1),0,h-1);
                int o=(y*w+x)*4,s=(yy*w+xx)*4;b[o]=s_FxScratch1[s];b[o+1]=s_FxScratch1[s+1];b[o+2]=s_FxScratch1[s+2];
            }break;}
        case FX_KALEIDOSCOPE:{
            int segs=std::max((int)e.p[0],2);
            EnsureScratch((size_t)w*h*4);
            memcpy(s_FxScratch1.data(),b,(size_t)w*h*4);
            float cx=w*0.5f,cy=h*0.5f;
            for(int y=0;y<h;y++)for(int x=0;x<w;x++){
                float dx=(x-cx),dy=(y-cy);
                float a=atan2f(dy,dx),d=sqrtf(dx*dx+dy*dy);
                float pa=3.14159265f/segs;
                float m=fmodf(fabsf(a),2*pa);if(m>pa)m=2*pa-m;
                int xx=clampf(cx+cosf(m)*d,0,w-1),yy=clampf(cy+sinf(m)*d,0,h-1);
                int o=(y*w+x)*4,s=(yy*w+xx)*4;b[o]=s_FxScratch1[s];b[o+1]=s_FxScratch1[s+1];b[o+2]=s_FxScratch1[s+2];
            }break;}
        case FX_GLOW:{
            int r=std::max(1,(int)e.p[0]);float amt=clampf(e.p[1],0,3);
            float thr=(e.p[2] > 0.001f) ? clampf(e.p[2],0.0f,1.0f) : 0.7f; // soft-knee threshold (old code hard-cut at 180/255)
            int mode=(int)e.p[3]; // 0 On Top (add), 1 Behind (glow only where source is transparent), 2 None (glow alone)
            int dw=w/4,dh=h/4;if(dw<2)dw=2;if(dh<2)dh=2;
            static std::vector<unsigned char> s_GlowSmall;
            static std::vector<unsigned char> s_GlowTmp;
            static std::vector<float> s_GlowKern;
            size_t reqSz = (size_t)dw * dh * 4;
            if(s_GlowSmall.size() < reqSz) s_GlowSmall.resize(reqSz);
            if(s_GlowTmp.size() < reqSz) s_GlowTmp.resize(reqSz);
            unsigned char* small = s_GlowSmall.data();
            unsigned char* tmp = s_GlowTmp.data();
            for(int sy=0;sy<dh;sy++)for(int sx=0;sx<dw;sx++){
                int ox=sx*4,oy=sy*4;
                float rr=0,gg=0,bb=0;int n=0;
                for(int dy=0;dy<4&&oy+dy<h;dy++)for(int dx=0;dx<4&&ox+dx<w;dx++){
                    int o=((oy+dy)*w+(ox+dx))*4;
                    rr+=b[o];gg+=b[o+1];bb+=b[o+2];n++;
                }
                if(n){rr/=n;gg/=n;bb/=n;}
                float lum=(rr*0.299f+gg*0.587f+bb*0.114f)/255.0f;
                float factor=clampf((lum-thr)/std::max(1e-3f,1.0f-thr),0.0f,1.0f); // soft knee, not a binary cut
                int o=(sy*dw+sx)*4;
                small[o]=(unsigned char)(rr*factor);small[o+1]=(unsigned char)(gg*factor);small[o+2]=(unsigned char)(bb*factor);small[o+3]=255;
            }
            int br=std::max(1,r/4);
            int sz=2*br+1;
            if(s_GlowKern.size() < (size_t)sz) s_GlowKern.resize(sz);
            float* kern = s_GlowKern.data();
            float ks=0;
            // ponytail: kernel spans the SMALL-image radius br (was copy-pasted (i-r)/r, which sampled
            // only the gaussian's left tail — an asymmetric ramp that smeared the halo off-center)
            for(int i=0;i<sz;i++){float x=(float)(i-br)/br;kern[i]=expf(-x*x*2.0f);ks+=kern[i];}
            for(int i=0;i<sz;i++)kern[i]/=ks;
            for(int y=0;y<dh;y++)for(int x=0;x<dw;x++){
                float rr=0,gg=0,bb=0;
                for(int k=-br;k<=br;k++){int xx=std::clamp(x+k,0,dw-1);int o=(y*dw+xx)*4;float wt=kern[k+br];rr+=small[o]*wt;gg+=small[o+1]*wt;bb+=small[o+2]*wt;}
                int o=(y*dw+x)*4;tmp[o]=(unsigned char)rr;tmp[o+1]=(unsigned char)gg;tmp[o+2]=(unsigned char)bb;tmp[o+3]=255;
            }
            // ponytail: V pass runs ONCE on the small image. The old code re-ran this kernel gather
            // per full-res pixel; the blur is linear/shift-invariant, so precomputing it and
            // nearest-upsampling yields identical values at ~1/16th the gathers.
            for(int y=0;y<dh;y++)for(int x=0;x<dw;x++){
                float rr=0,gg=0,bb=0;
                for(int k=-br;k<=br;k++){int yy=std::clamp(y+k,0,dh-1);int o=(yy*dw+x)*4;float wt=kern[k+br];rr+=tmp[o]*wt;gg+=tmp[o+1]*wt;bb+=tmp[o+2]*wt;}
                int o=(y*dw+x)*4;small[o]=(unsigned char)rr;small[o+1]=(unsigned char)gg;small[o+2]=(unsigned char)bb;small[o+3]=255;
            }
            for(int y=0;y<h;y++){int sy=y/4;if(sy>=dh)sy=dh-1;for(int x=0;x<w;x++){
                int sx=x/4;if(sx>=dw)sx=dw-1;
                int s=(sy*dw+sx)*4,o=(y*w+x)*4;
                float ga=small[s]*amt, gb=small[s+1]*amt, gc=small[s+2]*amt;
                if(mode == 2){ b[o]=(unsigned char)clampf(ga,0,255); b[o+1]=(unsigned char)clampf(gb,0,255); b[o+2]=(unsigned char)clampf(gc,0,255); }
                else if(mode == 1){ float k=1.0f-b[o+3]/255.0f; b[o]=(unsigned char)clampf(b[o]+ga*k,0,255); b[o+1]=(unsigned char)clampf(b[o+1]+gb*k,0,255); b[o+2]=(unsigned char)clampf(b[o+2]+gc*k,0,255); }
                else{ b[o]=(unsigned char)clampf(b[o]+ga,0,255); b[o+1]=(unsigned char)clampf(b[o+1]+gb,0,255); b[o+2]=(unsigned char)clampf(b[o+2]+gc,0,255); }
            }}break;}
        case FX_OUTLINE:FX_Outline(b,w,h,std::max(1,(int)e.p[0]),1.0f,1.0f,1.0f);break;
        case FX_SHADOW:FX_Shadow(b,w,h,(int)e.p[0],(int)e.p[1],e.p[3]);break; // p2 Blur was never implemented: ignored, not misread as color
        case FX_GRADIENT:FX_Gradient(b,w,h,e.p[0],e.p[1],e.p[2],e.p[3],e.p[4],e.p[5],e.p[6],e.p[7]);break;
        case FX_HALFTONE:FX_Halftone(b,w,h,e.p[0]);break;
        case FX_GRID:FX_Grid(b,w,h,e.p[0],e.p[1],e.p[2],e.p[3],e.p[4],e.p[5]);break;
        case FX_GHOST:FX_Ghost(b,w,h,e.p[0]);break;
        case FX_CHROMATIC:FX_Chromatic(b,w,h,(int)e.p[0]);break;
        case FX_LENS_FLARE:
            break;
        case FX_PIXELATE:FX_Mosaic(b,w,h,(int)e.p[0]);break;
        case FX_POSTERIZE:FX_Posterize(b,w,h,e.p[0]);break;
        case FX_COLOR_MATRIX:FX_ColorMatrix(b,w,h,e.p[0],e.p[1],e.p[2],e.p[3]);break;
        case FX_WIND:FX_Wind(b,w,h,e.p[0],(int)e.p[1]);break;
        case FX_LENS_DISTORT:FX_LensDistort(b,w,h,e.p[0],e.p[1]);break;
        case FX_PINCUSHION:FX_LensDistort(b,w,h,-e.p[0]*0.5f,0);break;
        case FX_BARREL:FX_LensDistort(b,w,h,e.p[0]*0.5f,0);break;
        case FX_FILM_GRAIN:{
            float amt=clampf(e.p[0],0,1);
            unsigned int seed=(unsigned int)(fxTime*60.0f)*2654435761u+0x9e3779b9u; // old: seed from dead p[1] = one frozen pattern forever
            for(int y=0;y<h;y++)for(int x=0;x<w;x++){
                seed=seed*1103515245+12345;
                float n=((float)((seed>>16)&0x7fff)/32767.0f-0.5f)*2.0f;
                int o=(y*w+x)*4;
                float g=n*amt*80.0f;
                b[o]=(unsigned char)clampf(b[o]+g,0,255);
                b[o+1]=(unsigned char)clampf(b[o+1]+g,0,255);
                b[o+2]=(unsigned char)clampf(b[o+2]+g,0,255);
            }break;}
        case FX_MOTION_BLUR:{
            int len=std::max(1,(int)e.p[0]);float ang=e.p[1]*3.14159265f/180.0f;
            float dx=cosf(ang),dy=sinf(ang);
            int st=len>16?(len+8)/16:1; // subsample long smears like the directional blurs
            EnsureScratch((size_t)w*h*4);
            memcpy(s_FxScratch1.data(),b,(size_t)w*h*4);
            for(int y=0;y<h;y++)for(int x=0;x<w;x++){
                float rr=0,gg=0,bb=0;int cnt=0;
                for(int i=-len;i<=len;i+=st){
                    int xx=(int)(x+dx*i),yy=(int)(y+dy*i);
                    if(xx<0||xx>=w||yy<0||yy>=h)continue;
                    int o=(yy*w+xx)*4;rr+=s_FxScratch1[o];gg+=s_FxScratch1[o+1];bb+=s_FxScratch1[o+2];cnt++;
                }
                int o=(y*w+x)*4;if(cnt){b[o]=(unsigned char)(rr/cnt);b[o+1]=(unsigned char)(gg/cnt);b[o+2]=(unsigned char)(bb/cnt);}
            }break;}
        case FX_SMART_DEPTH_BLUR:
            ApplySmartDepthBlur(b, w, h, e);
            break;
        case FX_LETTERBOX:{
            float top=clampf(e.p[0],0,0.45f);float bot=clampf(e.p[1],0,0.45f);
            int yt=(int)(top*h),yb=(int)(bot*h);
            for(int y=0;y<h;y++)for(int x=0;x<w;x++){
                if(y<yt||y>=h-yb){int o=(y*w+x)*4;b[o]=b[o+1]=b[o+2]=0;}
            }break;}
        case FX_LUT_COLOR:{
            float shadow=clampf(e.p[0],-1,1);
            float mid=clampf(e.p[1],-1,1);
            float highlight=clampf(e.p[2],-1,1);
            float sat=clampf(e.p[3],0,3);
            unsigned char curve[256]; // one shared lift/gamma curve: saturation needs all 3 channels, so it runs per-pixel below
            for(int i=0;i<256;i++){
                float t=i/255.0f;
                float lift=shadow*(1-t)+mid*t*0.5f+highlight*t*t;
                curve[i]=(unsigned char)(clampf(t+lift,0,1)*255);
            }
            for(int i=0;i<w*h*4;i+=4){
                float r=curve[b[i]],g=curve[b[i+1]],bl=curve[b[i+2]];
                float lum=r*0.299f+g*0.587f+bl*0.114f; // old code used luma-weights as channel values: everything went red at sat=1
                b[i]=(unsigned char)clampf(lum+(r-lum)*sat,0,255);
                b[i+1]=(unsigned char)clampf(lum+(g-lum)*sat,0,255);
                b[i+2]=(unsigned char)clampf(lum+(bl-lum)*sat,0,255);
            }
            break;}
        case FX_MOTION_TILE:{
            // ponytail: AE-style duplicate-tile recompose — p0 tile size %, p1 pan %, p2 output zoom %, p3 mirror
            float tileS = std::max(1.0f, e.p[0] > 0.0f ? e.p[0] : 100.0f);
            float outZ  = std::max(1.0f, e.p[2] > 0.0f ? e.p[2] : 100.0f);
            bool mirror = e.p[3] > 0.5f;
            float tz = 100.0f / tileS;   // tiles across the comp
            float oz = 100.0f / outZ;    // output window zoom
            float pan = e.p[1] / 100.0f;
            EnsureScratch((size_t)w*h*4);
            memcpy(s_FxScratch1.data(), b, (size_t)w*h*4);
            for(int y=0;y<h;y++)for(int x=0;x<w;x++){
                float nx = ((x/(float)w) - 0.5f) * oz + 0.5f;
                float ny = ((y/(float)h) - 0.5f) * oz + 0.5f;
                float tx = nx * tz + pan, ty = ny * tz + pan;
                float u = tx - floorf(tx), v = ty - floorf(ty);
                if(mirror){
                    long ix = (long)floorf(tx), iy = (long)floorf(ty);
                    if(ix & 1) u = 1.0f - u;
                    if(iy & 1) v = 1.0f - v;
                }
                int sx = std::min(w-1, (int)(u * (float)w));
                int sy = std::min(h-1, (int)(v * (float)h));
                int o=(y*w+x)*4, so=(sy*w+sx)*4;
                b[o]=s_FxScratch1[so]; b[o+1]=s_FxScratch1[so+1]; b[o+2]=s_FxScratch1[so+2]; b[o+3]=s_FxScratch1[so+3];
            }
            break;}
        default:break;
        }
    }
}

// Render individual item (Media or Text Layer) into target buffer
// ============ Media Foundation Video Engine ============
struct VideoData{
    std::string path;
    int w=0,h=0;
    double duration=0.0;      // seconds
    float fps=30.0f;
    IMFSourceReader* reader=nullptr;
    DWORD streamIdx=0;        // which stream holds video
    GUID nativeSubtype={0};   // decoded pixel format (e.g. NV12, RGB32)
    std::vector<unsigned char> frame; // packed RGBA cache
    double cacheTime=-1e9;            // media time of cached frame (seconds)
    int decStride=0;                  // cached decode stride (queried once; fixed for a file reader)
    bool decNV12=true, decBottomUp=false, decFmtKnown=false;
    std::vector<short> audioPCM; // mono? no — interleaved stereo 16-bit @44.1k, empty = silent footage
    std::vector<float> wave;    // lazy 128-col min/max pairs for the timeline waveform
};
static std::vector<VideoData> g_Videos;

static bool VideoGetFrame(VideoData& v,double t);
static void LoadVideoAudio(VideoData& v, const wchar_t* wpath);
static bool LoadAudioOnly(VideoData& v, const char* path);
static void MFEnsureStart(){ static bool s=false; if(!s){ MFStartup(MF_VERSION); s=true; } }

static bool LoadVideo(VideoData&v,const char*path){
    MFEnsureStart();
    wchar_t wpath[MAX_PATH]={0};
    MultiByteToWideChar(CP_UTF8,0,path,-1,wpath,MAX_PATH);
    IMFSourceReader* r=nullptr;
    HRESULT mkhr=MFCreateSourceReaderFromURL(wpath,nullptr,&r);
    if(FAILED(mkhr))return false;
    // find the VIDEO stream (stream 0 may be audio/cover art)
    DWORD vsi=(DWORD)-1;
    for(DWORD si=0; si<8; si++){
        IMFMediaType* nt=nullptr;
        if(FAILED(r->GetNativeMediaType(si,0,&nt)))continue;
        GUID maj={0}; nt->GetGUID(MF_MT_MAJOR_TYPE,&maj);
        nt->Release();
        if(maj==MFMediaType_Video){ vsi=si; break; }
    }
    if(vsi==(DWORD)-1){ r->Release(); return false; }
    if(FAILED(r->SetStreamSelection((DWORD)MF_SOURCE_READER_ALL_STREAMS,FALSE))||
       FAILED(r->SetStreamSelection(vsi,TRUE))){ r->Release(); return false; }
    // request DECODED output: NV12 preferred (native decoder output), RGB32 fallback
    GUID sub={0}; UINT64 fsz=0; UINT32 num=0,den=1;
    HRESULT shr=E_FAIL;
    const GUID wantSub[2]={MFVideoFormat_NV12,MFVideoFormat_RGB32};
    for(int wi=0; wi<2 && FAILED(shr); wi++){
        IMFMediaType* want=nullptr;
        if(SUCCEEDED(MFCreateMediaType(&want))){
            want->SetGUID(MF_MT_MAJOR_TYPE,MFMediaType_Video);
            want->SetGUID(MF_MT_SUBTYPE,wantSub[wi]);
            shr=r->SetCurrentMediaType(vsi,nullptr,want);
            want->Release();
        }
    }
    if(FAILED(shr)){ r->Release(); return false; }
    {
        IMFMediaType* cur=nullptr;
        if(SUCCEEDED(r->GetCurrentMediaType(vsi,&cur))){
            cur->GetGUID(MF_MT_SUBTYPE,&sub);
            UINT32 fw=0,fh=0;
            if(SUCCEEDED(MFGetAttributeSize(cur,MF_MT_FRAME_SIZE,&fw,&fh))) fsz=((UINT64)fw<<32)|fh;
            UINT32 n2=0,d2=1;
            if(SUCCEEDED(MFGetAttributeRatio(cur,MF_MT_FRAME_RATE,&n2,&d2))&&d2>0){num=n2;den=d2;}
            cur->Release();
        }
    }
    v.w=(int)(fsz>>32); v.h=(int)(fsz&0xFFFFFFFF);
    if(den>0) v.fps=(float)num/(float)den;
    v.nativeSubtype=sub;
    v.streamIdx=vsi;
    if(v.w<=0||v.h<=0){ r->Release(); return false; }
    PROPVARIANT pv; PropVariantInit(&pv);
    if(SUCCEEDED(r->GetPresentationAttribute((DWORD)MF_SOURCE_READER_MEDIASOURCE,MF_PD_DURATION,&pv))){
        if(pv.vt==VT_UI8) v.duration=std::max(0.01,(double)pv.hVal.QuadPart/1e7); // other variant types = garbage duration
        else v.duration=0.01;
    }
    PropVariantClear(&pv);
    v.frame.resize((size_t)v.w*v.h*4);
    v.path=path; v.reader=r; v.cacheTime=-1e9;
    LoadVideoAudio(v, wpath); // non-fatal: silent footage simply has empty audioPCM
    return true;
}

// ponytail: audio lives on a SECOND SourceReader so music/VO decode never disturbs the video
// stream position. Whole-file PCM @44.1k stereo, capped at 180s (~31MB) for the 4GB floor.
static const int AU_RATE = 44100, AU_CH = 2;
static const float AU_MAX_SEC = 180.0f;
static bool DecodeAudioStream(IMFSourceReader* ar, DWORD asi, VideoData& v){
    IMFMediaType* pcm=nullptr;
    if(SUCCEEDED(MFCreateMediaType(&pcm))){
        pcm->SetGUID(MF_MT_MAJOR_TYPE,MFMediaType_Audio);
        pcm->SetGUID(MF_MT_SUBTYPE,MFAudioFormat_PCM);
        pcm->SetUINT32(MF_MT_AUDIO_NUM_CHANNELS,AU_CH);
        pcm->SetUINT32(MF_MT_AUDIO_SAMPLES_PER_SECOND,AU_RATE);
        pcm->SetUINT32(MF_MT_AUDIO_BITS_PER_SAMPLE,16);
        pcm->SetUINT32(MF_MT_AUDIO_BLOCK_ALIGNMENT,AU_CH*2);
        pcm->SetUINT32(MF_MT_AUDIO_AVG_BYTES_PER_SECOND,AU_RATE*AU_CH*2);
        if(FAILED(ar->SetCurrentMediaType(asi,nullptr,pcm))){ pcm->Release(); return false; }
        pcm->Release();
    }
    size_t capBytes=(size_t)(AU_RATE*AU_MAX_SEC)*AU_CH*2;
    v.audioPCM.reserve((size_t)(AU_RATE*30)*AU_CH); // typical song: pre-grow once, no re-alloc churn
    for(int guard=0; guard<4000; guard++){
        IMFSample* smp=nullptr; DWORD flags=0;
        ar->ReadSample(asi,0,nullptr,&flags,nullptr,&smp);
        if(flags&MF_SOURCE_READERF_ENDOFSTREAM){ if(smp)smp->Release(); break; }
        if(!smp) continue;
        IMFMediaBuffer* mb=nullptr;
        if(SUCCEEDED(smp->ConvertToContiguousBuffer(&mb))){
            BYTE* data=nullptr; DWORD maxLen=0,curLen=0;
            if(SUCCEEDED(mb->Lock(&data,&maxLen,&curLen))){
                bool capped = false;
                if(curLen > 0){
                    size_t have=v.audioPCM.size()*2, room=(capBytes>have)?capBytes-have:0;
                    size_t take=(curLen<room)?curLen:room;
                    size_t old=v.audioPCM.size();
                    v.audioPCM.resize(old+(take&~(size_t)1)/2);
                    memcpy(v.audioPCM.data()+old,data,take&~(size_t)1);
                    capped = (take<curLen);
                }
                mb->Unlock();
                if(capped){ mb->Release(); smp->Release(); break; } // hit the cap
            }
        }
        if(mb)mb->Release();
        smp->Release();
    }
    return !v.audioPCM.empty();
}
static DWORD FindAudioStream(IMFSourceReader* ar){
    for(DWORD si=0; si<8; si++){
        IMFMediaType* nt=nullptr;
        if(FAILED(ar->GetNativeMediaType(si,0,&nt))) continue;
        GUID maj={0}; nt->GetGUID(MF_MT_MAJOR_TYPE,&maj);
        nt->Release();
        if(maj==MFMediaType_Audio) return si;
    }
    return (DWORD)-1;
}
static void LoadVideoAudio(VideoData& v, const wchar_t* wpath){
    IMFSourceReader* ar=nullptr;
    if(FAILED(MFCreateSourceReaderFromURL(wpath,nullptr,&ar))) return;
    DWORD asi = FindAudioStream(ar);
    if(asi==(DWORD)-1){ ar->Release(); return; }
    if(FAILED(ar->SetStreamSelection((DWORD)MF_SOURCE_READER_ALL_STREAMS,FALSE)) ||
       FAILED(ar->SetStreamSelection(asi,TRUE))){ ar->Release(); return; }
    DecodeAudioStream(ar, asi, v);
    ar->Release();
}
static bool LoadAudioOnly(VideoData& v, const char* path){ // music/SFX files: no video stream at all
    MFEnsureStart();
    wchar_t wpath[MAX_PATH]={0};
    MultiByteToWideChar(CP_UTF8,0,path,-1,wpath,MAX_PATH);
    IMFSourceReader* ar=nullptr;
    if(FAILED(MFCreateSourceReaderFromURL(wpath,nullptr,&ar))) return false;
    DWORD asi = FindAudioStream(ar);
    if(asi==(DWORD)-1){ ar->Release(); return false; }
    if(FAILED(ar->SetStreamSelection((DWORD)MF_SOURCE_READER_ALL_STREAMS,FALSE)) ||
       FAILED(ar->SetStreamSelection(asi,TRUE))){ ar->Release(); return false; }
    if(!DecodeAudioStream(ar, asi, v)){ ar->Release(); return false; }
    ar->Release();
    v.path=path; v.w=0; v.h=0; v.fps=30.0f; v.reader=nullptr; v.cacheTime=-1e9;
    v.duration=std::max(0.01,(double)(v.audioPCM.size()/2)/AU_RATE); // exact: measured from the decoded samples
    return true;
}

static bool VideoGetFrame(VideoData&v,double t){
    if(!v.reader)return false;
    double halfFps = 0.5/std::max(1.0f,v.fps);
    if(fabs(v.cacheTime-t)<halfFps)return true;          // cached
    t=clampd(t,0.0,std::max(0.0,v.duration-0.001));
    LONGLONG target=(LONGLONG)(t*1e7);
    // seek when moving backward or jumping far forward
    if(v.cacheTime<-1e8 || t<v.cacheTime-halfFps || t>v.cacheTime+0.6){
        PROPVARIANT pos; PropVariantInit(&pos);
        pos.vt=VT_I8; pos.hVal.QuadPart=target;
        v.reader->SetCurrentPosition(GUID_NULL,pos);
        PropVariantClear(&pos);
    }
    int stride=4*v.w; bool bottomUp=true; bool isNV12=false;
    // ponytail: the decoded subtype/stride never change for a file reader — query once, not per frame
    if(!v.decFmtKnown){
        IMFMediaType* cur=nullptr;
        if(SUCCEEDED(v.reader->GetCurrentMediaType(v.streamIdx,&cur))){
            INT32 st=0;
            PROPVARIANT spv; PropVariantInit(&spv);
            if(SUCCEEDED(cur->GetBlob(MF_MT_DEFAULT_STRIDE,(BYTE*)&st,sizeof(INT32),nullptr))&&st!=0) stride=abs(st);
            GUID sub={0}; cur->GetGUID(MF_MT_SUBTYPE,&sub);
            isNV12=(sub==v.nativeSubtype)&&(sub==MFVideoFormat_NV12);
            if(isNV12){ if(st!=0)stride=abs(st); else stride=v.w; bottomUp=false; }
            else bottomUp = st<0 || (st==0 && stride>0); // RGB32 from Source Reader is typically bottom-up DIB
            PropVariantClear(&spv);
            cur->Release();
        }
        v.decStride=stride; v.decNV12=isNV12; v.decBottomUp=bottomUp; v.decFmtKnown=true;
    }else{
        stride=v.decStride; isNV12=v.decNV12; bottomUp=v.decBottomUp;
    }
    const double eps=halfFps*0.9;
    for(int guard=0;guard<180;guard++){                  // decode up to ~3s past seek point
        IMFSample* smp=nullptr; DWORD flags=0;
        v.reader->ReadSample(v.streamIdx,0,nullptr,&flags,nullptr,&smp);
        // failure surfaces as !smp below; guard loop bounds the retries
        if(flags&MF_SOURCE_READERF_ENDOFSTREAM){ if(smp)smp->Release(); break; }
        if(!smp)continue;
        LONGLONG pts=0;
        smp->GetSampleTime(&pts);
        double sec=(double)pts/1e7;
        // ponytail: only convert the frame we will display. Forward stepping (timelapse speed,
        // scrub jumps) decodes k frames to show the last — converting the k-1 intermediates is
        // pure waste. (Sequential playback converts every frame it shows, so it keeps full cost.)
        if(sec < t-eps){ smp->Release(); continue; }
        IMFMediaBuffer* mb=nullptr;
        if(SUCCEEDED(smp->ConvertToContiguousBuffer(&mb))){
            BYTE* data=nullptr; DWORD maxLen=0,curLen=0;
            DWORD needLen=(DWORD)(stride*(isNV12?((size_t)v.h*3)/2:(size_t)v.h));
            if(SUCCEEDED(mb->Lock(&data,&maxLen,&curLen))){
                if(curLen>=needLen){
                if(isNV12){
                    // NV12: Y plane (stride*h) then interleaved CbCr plane at half height
                    // ponytail: integer BT.709 (x256, >>8) + one CbCr load per pixel pair.
                    // Old path: ~15 float ops + 3 clamps per pixel. Visually identical (+/-1 LSB).
                    const unsigned char* Y=data;
                    const unsigned char* UV=data+(size_t)stride*v.h;
                    for(int y=0;y<v.h;y++){
                        const unsigned char* yrow=Y+(size_t)y*stride;
                        const unsigned char* uvrow=UV+(size_t)(y/2)*stride;
                        unsigned char* dst=&v.frame[(size_t)y*v.w*4];
                        for(int x=0;x<v.w;x+=2){
                            int uvo=x&~1; // odd widths: (uvo+1) can equal stride when stride==w; clamp, don't over-read
                            int cb=(int)uvrow[uvo]-128;
                            int cr=(int)uvrow[uvo+(uvo+1<stride?1:0)]-128;
                            for(int k=0;k<2 && x+k<v.w;k++){
                                int l=(int)yrow[x+k]-16;
                                int r=(298*l+459*cr+128)>>8;
                                int g=(298*l-55*cr-137*cb+128)>>8;
                                int b=(298*l+541*cb+128)>>8;
                                r=r<0?0:(r>255?255:r);
                                g=g<0?0:(g>255?255:g);
                                b=b<0?0:(b>255?255:b);
                                dst[(x+k)*4+0]=(unsigned char)r;
                                dst[(x+k)*4+1]=(unsigned char)g;
                                dst[(x+k)*4+2]=(unsigned char)b;
                                dst[(x+k)*4+3]=255;
                            }
                        }
                    }
                }else{
                    const BYTE* srcRows=data;
                    if(bottomUp) srcRows=data+(size_t)(v.h-1)*stride;
                    for(int y=0;y<v.h;y++){
                        const BYTE* row=srcRows+(bottomUp?-(size_t)y:(size_t)y)*stride;
                        unsigned char* dst=&v.frame[(size_t)y*v.w*4];
                        for(int x=0;x<v.w;x++){
                            const BYTE* px=row+x*4;         // BGRA -> RGBA
                            dst[x*4+0]=px[2]; dst[x*4+1]=px[1]; dst[x*4+2]=px[0]; dst[x*4+3]=255;
                        }
                    }
                }
                v.cacheTime=sec;
            }
            mb->Unlock(); // a successful Lock must always be unlocked, even when the buffer is short
        }
        }
        if(mb)mb->Release();
        smp->Release();
        if(sec>=t-eps)break;                             // reached requested time
    }
    return !v.frame.empty();
}

static void FreeVideos(){
    for(auto&v:g_Videos){ if(v.reader){ v.reader->Flush(0); v.reader->Release(); } }
    g_Videos.clear();
}

// ============ Preview Audio (decode-on-load PCM + waveOut feeder) ============
static HWAVEOUT s_Wave = nullptr;
static const int AU_CHUNK = 11025; // 0.25s @44.1k
static WAVEHDR s_Whdr[4];
static short s_WBuf[4][AU_CHUNK*2];
static bool s_WInit = false;
static float s_StreamT = 0.0f;
static bool s_StreamOn = false;
static void AudioStop(){
    if(!s_StreamOn && !s_Wave) return;
    s_StreamOn = false;
    if(s_Wave){
        waveOutReset(s_Wave); // drop queued chunks: pause/scrub/mute respond instantly
        for(int i = 0; i < 4; i++)
            if(s_Whdr[i].dwFlags & WHDR_PREPARED){ waveOutUnprepareHeader(s_Wave, &s_Whdr[i], sizeof(WAVEHDR)); s_Whdr[i].dwFlags = 0; }
    }
}
static void AudioShutdown(){ AudioStop(); if(s_Wave){ waveOutClose(s_Wave); s_Wave = nullptr; } }
static void MixAudioRange(float t0, int nFrames, float* acc){ // mix nFrames of stereo @44.1k into acc (export + preview share this)
    memset(acc, 0, (size_t)nFrames*2*sizeof(float));
    for(auto& c : g_Clips){
        if(c.videoIdx < 0 || c.videoIdx >= (int)g_Videos.size()) continue;
        const VideoData& vd = g_Videos[c.videoIdx];
        if(vd.audioPCM.empty()) continue;
        if(c.track < 0 || c.track >= (int)g_TrackVisible.size() || !g_TrackVisible[c.track]) continue; // hidden track = silent
        float spd = std::max(0.1f, c.speed);
        float w0 = c.startTime, w1 = w0 + c.duration * spd;
        if(t0 + (float)nFrames / AU_RATE > w0 && t0 < w1){
            size_t nFr = vd.audioPCM.size() / 2;
            for(int f = 0; f < nFrames; f++){
                float lt = (t0 + (float)f / AU_RATE - w0) / spd + c.srcOff;
                if(lt < 0.0f || lt > c.duration) continue;
                size_t si = (size_t)(lt * AU_RATE);
                if(si < nFr){ acc[f*2] += vd.audioPCM[si*2] / 32768.0f; acc[f*2+1] += vd.audioPCM[si*2+1] / 32768.0f; }
            }
        }
    }
}
static void MixAudioChunk(float t0, short* out){
    static float acc[AU_CHUNK*2]; // 88KB: static, not stack
    MixAudioRange(t0, AU_CHUNK, acc);
    for(int i = 0; i < AU_CHUNK*2; i++) out[i] = (short)clampf(acc[i] * 32767.0f, -32768.0f, 32767.0f);
}
static void AudioFeed(){
    if(g_AudioMuted){ AudioStop(); return; }
    bool any = false;
    for(auto& c : g_Clips){
        if(c.videoIdx < 0 || c.videoIdx >= (int)g_Videos.size()) continue;
        if(g_Videos[c.videoIdx].audioPCM.empty()) continue;
        if(c.track < 0 || c.track >= (int)g_TrackVisible.size() || !g_TrackVisible[c.track]) continue;
        any = true; break;
    }
    if(!any){ AudioStop(); return; }
    if(!s_Wave){
        WAVEFORMATEX wfx = {WAVE_FORMAT_PCM, AU_CH, AU_RATE, AU_RATE*AU_CH*2, AU_CH*2, 16, 0};
        if(waveOutOpen(&s_Wave, WAVE_MAPPER, &wfx, 0, 0, CALLBACK_NULL) != MMSYSERR_NOERROR){ s_Wave = nullptr; return; }
        if(!s_WInit){ memset(s_Whdr, 0, sizeof s_Whdr); s_WInit = true; }
    }
    if(!s_StreamOn || fabsf(s_StreamT - g_PlayTime) > 0.75f){ AudioStop(); s_StreamT = g_PlayTime; s_StreamOn = true; } // seek/work-loop jump: resync
    for(int i = 0; i < 4; i++) // reclaim played buffers
        if((s_Whdr[i].dwFlags & WHDR_PREPARED) && (s_Whdr[i].dwFlags & WHDR_DONE)){ waveOutUnprepareHeader(s_Wave, &s_Whdr[i], sizeof(WAVEHDR)); s_Whdr[i].dwFlags = 0; }
    int queued = 0;
    for(int i = 0; i < 4; i++) if(s_Whdr[i].dwFlags & WHDR_PREPARED) queued++;
    float endT = WorkAreaActive() ? g_WorkOut : TotalDur();
    while(queued < 3 && s_StreamT < endT){
        int slot = -1;
        for(int i = 0; i < 4; i++) if(!(s_Whdr[i].dwFlags & WHDR_PREPARED)){ slot = i; break; }
        if(slot < 0) break;
        MixAudioChunk(s_StreamT, s_WBuf[slot]);
        memset(&s_Whdr[slot], 0, sizeof(WAVEHDR));
        s_Whdr[slot].lpData = (LPSTR)s_WBuf[slot];
        s_Whdr[slot].dwBufferLength = sizeof s_WBuf[slot];
        if(waveOutPrepareHeader(s_Wave, &s_Whdr[slot], sizeof(WAVEHDR)) != MMSYSERR_NOERROR) break;
        if(waveOutWrite(s_Wave, &s_Whdr[slot], sizeof(WAVEHDR)) != MMSYSERR_NOERROR){ waveOutUnprepareHeader(s_Wave, &s_Whdr[slot], sizeof(WAVEHDR)); s_Whdr[slot].dwFlags = 0; break; }
        s_StreamT += (float)AU_CHUNK / AU_RATE;
        queued++;
    }
}

static void RenderTimelineItem(unsigned char*b,int w,int h,const TimelineItem&c,const Camera&cam,float localTime=0.0f){
    if(!c.visible) return;
    int trIdx = c.track;
    if(trIdx < 0 || trIdx >= (int)g_TrackVisible.size() || !g_TrackVisible[trIdx]) return;
    float eOp = EvaluateClipOpacity(c, localTime) * c.opacity; // ponytail: keys animate the Opacity slider too
    if(c.type == ITEM_MEDIA){
        unsigned char* srcPx=nullptr; int sw=0, sh=0;
        if(c.videoIdx>=0 && c.videoIdx<(int)g_Videos.size()){
            VideoData&vd=g_Videos[c.videoIdx];
            if(vd.frame.empty())return;
            srcPx=vd.frame.data(); sw=vd.w; sh=vd.h;
        }else{
            int gi=c.imageIdx;if(gi<0||gi>=(int)g_Images.size())return;
            ImageData&im=g_Images[gi];
            if(!im.px || im.w <= 0 || im.h <= 0)return;
            srcPx=im.px; sw=im.w; sh=im.h;
        }
        
        float scaleVal = std::max(0.01f, cam.zoom);
        float compAspect = (float)w / (float)h;
        float imgAspect = (float)sw / (float)sh;
        float scaleX = 1.0f, scaleY = 1.0f;
        if(imgAspect >= compAspect){
            scaleX = 1.0f;
            scaleY = compAspect / imgAspect;
        }else{
            scaleX = imgAspect / compAspect;
            scaleY = 1.0f;
        }

        float br=(c.color.bright)*1.0f;
        float ct=c.color.contrast+1.0f;
        bool needGrade = (br != 0.0f || ct != 1.0f || c.color.sat != 1.0f); // ponytail: skip per-pixel grade math on identity

        float cosR = cosf(cam.rot);
        float sinR = sinf(cam.rot);
        float invW = 1.0f / (float)w;
        float invH = 1.0f / (float)h;
        float halfW = (float)w * 0.5f;
        float halfH = (float)h * 0.5f;
        float invScaleVal = 1.0f / scaleVal;
        float invSX = 1.0f / scaleX;
        float invSY = 1.0f / scaleY;

        float d_rx = cosR * invW;
        float d_ry = sinR * invW;
        float d_u = (d_rx * invSX) * invScaleVal;
        float d_v = (d_ry * invSY) * invScaleVal;
        float dsx = d_u * sw;
        float dsy = d_v * sh;
        float swHalf = sw * 0.5f;
        float shHalf = sh * 0.5f;

        if(cam.rot == 0.0f){
            // ponytail: axis-aligned fast path — one shared column recurrence, hoisted row pointers,
            // no per-pixel clamps/mults/calls. Covers ~all footage; rotation uses the general path.
            // Maps replicate the general loop's recurrence exactly: bit-identical output.
            float nx0 = -halfW * invW;
            float sxInit = swHalf + (((nx0 * invSX) - (float)cam.px) * invScaleVal) * sw;
            WarpMapFill(w, sxInit, dsx, (float)sw, s_WarpX0, s_WarpXf);
            if((int)s_WarpY0.size() < h){ s_WarpY0.resize(h); s_WarpYf.resize(h); }
            for(int y=0; y<h; y++){
                float ny = (y - halfH) * invH;
                float syv = shHalf + (((ny * invSY) - (float)cam.py) * invScaleVal) * sh;
                if(syv < 0.0f || syv >= (float)sh){ s_WarpY0[y] = -1; s_WarpYf[y] = 0.0f; continue; }
                float cy = clampf(syv, 0.0f, (float)sh - 1.0001f);
                s_WarpY0[y] = (int)cy; s_WarpYf[y] = cy - s_WarpY0[y];
            }
            for(int y=0; y<h; y++){
                int y0 = s_WarpY0[y];
                if(y0 < 0) continue;
                float fy = s_WarpYf[y];
                int y1 = y0+1; if(y1>=sh)y1=sh-1;
                const unsigned char* r0 = srcPx + (size_t)y0*sw*4;
                const unsigned char* r1 = srcPx + (size_t)y1*sw*4;
                float ify = 1.0f - fy;
                int yw = y * w;
                for(int x=0; x<w; x++){
                    int x0 = s_WarpX0[x];
                    if(x0 < 0) continue;
                    float fx = s_WarpXf[x];
                    int x1 = x0+1; if(x1>=sw)x1=sw-1;
                    const unsigned char* p00 = r0 + x0*4;
                    const unsigned char* p10 = r0 + x1*4;
                    const unsigned char* p01 = r1 + x0*4;
                    const unsigned char* p11 = r1 + x1*4;
                    float ifx = 1.0f - fx;
                    int o = (yw+x)*4;
                    unsigned char col[3];
                    for(int k=0;k<3;k++){
                        float v=(p00[k]*ifx+p10[k]*fx)*ify+(p01[k]*ifx+p11[k]*fx)*fy;
                        col[k]=(unsigned char)v;
                    }
                    if(needGrade) GradePixel(col, br, ct, c.color.sat);
                    b[o]=col[0];b[o+1]=col[1];b[o+2]=col[2];b[o+3]=255;
                }
            }
        }else{
        for(int y=0; y<h; y++){
            float ny = (y - halfH) * invH;
            float nx0 = -halfW * invW;
            float rx0 = cosR * nx0 - sinR * ny;
            float ry0 = sinR * nx0 + cosR * ny;
            float u0 = ((rx0 * invSX) - (float)cam.px) * invScaleVal;
            float v0 = ((ry0 * invSY) - (float)cam.py) * invScaleVal;
            float sx = swHalf + u0 * sw;
            float sy = shHalf + v0 * sh;
            int yw = y * w;

            for(int x=0; x<w; x++, sx += dsx, sy += dsy){
                if(sx < 0.0f || sx >= (float)sw || sy < 0.0f || sy >= (float)sh){
                    continue;
                }

                int o=(yw+x)*4;
                unsigned char col[3];
                Sample(srcPx,sw,sh,sx,sy,col);
                if(needGrade) GradePixel(col, br, ct, c.color.sat);

                b[o]=col[0];b[o+1]=col[1];b[o+2]=col[2];b[o+3]=255;
            }
        }
        }
        ApplyFXPipeline(b,w,h,c.fx,localTime);
        if(eOp < 0.999f){ for(size_t oi = 3; oi < (size_t)w * h * 4; oi += 4) b[oi] = (unsigned char)(b[oi] * eOp); }
    }else if(c.type == ITEM_TEXT){
        int fs=(int)(c.fontSize/720.0f*h);
        DrawTextToBuffer(b, w, h, c.textContent, fs, w/2, h/2,
            (unsigned char)clampf(c.textColor[0]*255,0,255),
            (unsigned char)clampf(c.textColor[1]*255,0,255),
            (unsigned char)clampf(c.textColor[2]*255,0,255),
            eOp, c.fontIdx, &cam, &c.anim, localTime, c.duration);
        ApplyFXPipeline(b,w,h,c.fx,localTime);
    }
}

// Alpha Composite src over dst
static void CompositeLayer(unsigned char*dst, const unsigned char*src, int w, int h){
    for(int i = 0; i < w * h * 4; i += 4){
        unsigned char sa_u = src[i+3];
        if(sa_u == 0) continue;
        if(sa_u == 255){
            dst[i] = src[i]; dst[i+1] = src[i+1]; dst[i+2] = src[i+2]; dst[i+3] = 255;
        }else{
            float sa = sa_u / 255.0f;
            float da = dst[i+3] / 255.0f;
            float invSa = 1.0f - sa;
            float outA = sa + da * invSa;
            if(outA > 0.0f){
                float invOutA = 1.0f / outA;
                dst[i]   = (unsigned char)clampf((src[i] * sa + dst[i] * da * invSa) * invOutA, 0.0f, 255.0f);
                dst[i+1] = (unsigned char)clampf((src[i+1] * sa + dst[i+1] * da * invSa) * invOutA, 0.0f, 255.0f);
                dst[i+2] = (unsigned char)clampf((src[i+2] * sa + dst[i+2] * da * invSa) * invOutA, 0.0f, 255.0f);
                dst[i+3] = (unsigned char)clampf(outA * 255.0f, 0.0f, 255.0f);
            }
        }
    }
}

// ============ Multi-Track Composition Preview ============
static void RenderPreview(float t,int W,int H,unsigned char*buf){
    // ponytail: single 32-bit fill of opaque black — was memset + a redundant per-pixel loop (2 passes).
    // Windows-only codebase: unsigned int is 4 bytes; RGBA byte order => 0xFF000000.
    unsigned int* pw = (unsigned int*)buf;
    size_t npix = (size_t)W * H;
    for(size_t i = 0; i < npix; i++) pw[i] = 0xFF000000u;
    if(g_Clips.empty()) return;

    EnsureScratch((size_t)W*H*4);

    int maxTrack = 0;
    int smartDepthFocalTrack = -1;
    float smartDepthRadius = 0.0f;

    for(const auto& item : g_Clips){
        if(item.track > maxTrack) maxTrack = item.track;
        float st = item.startTime;
        float dur = item.duration * std::max(0.1f, item.speed);
        if(t >= st && t <= st + dur){
            for(const auto& e : item.fx){
                if(e.type == FX_SMART_DEPTH_BLUR && e.enabled && (int)e.p[3] == 0){
                    smartDepthFocalTrack = item.track;
                    smartDepthRadius = e.p[0] > 0.1f ? e.p[0] : 18.0f;
                    break;
                }
            }
        }
    }

    for(int tr = 0; tr <= maxTrack; tr++){
        for(size_t ci = 0; ci < g_Clips.size(); ci++){
            const auto& item = g_Clips[ci];
            if(item.track != tr) continue;
            float st = item.startTime;
            float dur = item.duration * std::max(0.1f, item.speed);
            if(t < st || t > st + dur) continue;

            float lt = clampf((t - st) / std::max(0.1f, item.speed) + item.srcOff, 0.0f, item.duration);
            Camera cam = EvaluateClipTransform(item, lt);

            if(item.motionBlur){
                // ponytail: multi-tap temporal blur. More taps + triangle weights = smooth smear on fast layers;
                // consecutive identical ltk taps dedupe (video near-frame boundaries) so cost stays low on the i3 floor.
                int taps = (item.shutterAngle <= 90) ? 4 : (item.shutterAngle <= 180) ? 6 : (item.shutterAngle <= 270) ? 8 : 10;
                float spread = (clampf((float)item.shutterAngle, 1.0f, 360.0f) / 360.0f) / std::max(1.0f, g_FPS);
                size_t sz = (size_t)W*H*4;
                if(s_MbTap.size() < sz) s_MbTap.resize(sz);
                // ponytail: additive accumulation with per-pixel weight normalization.
                // Old blend formula diluted the reference frame to ~(1/N)^N causing darkening.
                // New: sum RGB*weight per pixel, track per-pixel total weight, normalize at end.
                // Buffers persist across frames (grow-once + memset); the old per-frame vector
                // allocs cost a multi-MB malloc+zero per motion-blurred clip per frame.
                size_t wsz = (size_t)W*H;
                if(s_MbSum.size() < sz){ s_MbSum.resize(sz); s_MbWts.resize(wsz); }
                float* sum = s_MbSum.data();
                float* wts = s_MbWts.data();
                memset(sum, 0, sz * sizeof(float));
                memset(wts, 0, wsz * sizeof(float));
                float spd = std::max(0.1f, item.speed);
                float ltVals[12]; int lCnt[12]; float lW[12]; int nU = 0;
                for(int tk = 0; tk < taps; tk++){
                    float gtk = t - spread*0.5f + (taps > 1 ? tk*spread/(float)(taps-1) : 0.0f);
                    float ltk = clampf((gtk - st) / spd + item.srcOff, 0.0f, item.duration);
                    if(nU == 0 || fabsf(ltk - ltVals[nU-1]) > 1e-4f){
                        ltVals[nU] = ltk; lCnt[nU] = 1;
                        lW[nU] = 1.0f + (float)std::min(tk, taps-1-tk); // triangle: middle taps weigh most
                        nU++;
                    }else{
                        lCnt[nU-1]++;
                    }
                }
                float wSum = 0.0f;
                for(int u = 0; u < nU; u++) wSum += lW[u] * (float)lCnt[u];
                for(int u = 0; u < nU; u++){
                    float gtk = st + ltVals[u] * spd;
                    if(item.videoIdx>=0 && item.videoIdx<(int)g_Videos.size()){
                        VideoData&vd=g_Videos[item.videoIdx];
                        VideoGetFrame(vd,clampd((double)ltVals[u],0.0,std::max(0.0,vd.duration-0.001))); // ltVals already media-time (+srcOff); *(speed) here squared the rate
                    }
                    Camera camK = EvaluateClipTransform(item, ltVals[u]);
                    // ponytail: clear per tap — media/text paths leave uncovered pixels untouched,
                    // so without this tap u-1's pixels leak into tap u's accumulation (ghosting).
                    memset(s_MbTap.data(), 0, sz);
                    RenderTimelineItem(s_MbTap.data(), W, H, item, camK, ltVals[u]);
                    float wnorm = (lW[u] * (float)lCnt[u]) / wSum;
                    unsigned char* tap = s_MbTap.data();
                    for(int py = 0; py < H; py++) for(int px = 0; px < W; px++){
                        int oi = (py*W+px)*4;
                        if(tap[oi+3] > 0){
                            sum[oi]   += tap[oi]   * wnorm;
                            sum[oi+1] += tap[oi+1] * wnorm;
                            sum[oi+2] += tap[oi+2] * wnorm;
                            wts[py*W+px] += wnorm;
                        }
                    }
                }
                unsigned char* acc = s_LayerBuf.data();
                // ponytail: taps carry per-tap opacity in alpha, but accumulation normalizes it away —
                // reapply the current-frame opacity here, or MB clips ignore the Opacity slider/keys.
                unsigned char mbAlpha = (unsigned char)(255.0f * clampf(EvaluateClipOpacity(item, lt) * item.opacity, 0.0f, 1.0f));
                for(int py = 0; py < H; py++) for(int px = 0; px < W; px++){
                    int oi = (py*W+px)*4;
                    float w = wts[py*W+px];
                    if(w > 1e-4f){
                        float inv = 1.0f / w;
                        acc[oi]   = (unsigned char)std::min(255, (int)(sum[oi]   * inv + 0.5f));
                        acc[oi+1] = (unsigned char)std::min(255, (int)(sum[oi+1] * inv + 0.5f));
                        acc[oi+2] = (unsigned char)std::min(255, (int)(sum[oi+2] * inv + 0.5f));
                        acc[oi+3] = mbAlpha;
                    }else{
                        acc[oi] = acc[oi+1] = acc[oi+2] = acc[oi+3] = 0;
                    }
                }
            }else{
                if(item.videoIdx>=0 && item.videoIdx<(int)g_Videos.size()){
                    VideoData&vd=g_Videos[item.videoIdx];
                    VideoGetFrame(vd,clampd((double)lt,0.0,std::max(0.0,vd.duration-0.001))); // lt is media-time (+srcOff); the old (t-st)*speed froze tailed clips
                }

                memset(s_LayerBuf.data(), 0, (size_t)W*H*4);
                RenderTimelineItem(s_LayerBuf.data(), W, H, item, cam, lt);
            }

            if(smartDepthFocalTrack >= 0 && tr != smartDepthFocalTrack && smartDepthRadius > 0.5f){
                int trackDist = abs(tr - smartDepthFocalTrack);
                FXParams autoDepthFx;
                autoDepthFx.type = FX_SMART_DEPTH_BLUR;
                autoDepthFx.p[0] = std::min(35.0f, smartDepthRadius * trackDist * 0.8f);
                autoDepthFx.p[3] = 0; // mode lives in p[3] (see ApplySmartDepthBlur); p[6] left the auto-blur permanently radial
                ApplySmartDepthBlur(s_LayerBuf.data(), W, H, autoDepthFx);
            }

            CompositeLayer(buf, s_LayerBuf.data(), W, H);
        }
    }
}

static void UploadPrev(bool nearestMag = false){ // zoomed-in views upscale: NEAREST keeps pixels crisp instead of blurry
    if(!g_PrevBuf||g_PrevW<=0||g_PrevH<=0)return;
    if(!g_PrevTex){glGenTextures(1,&g_PrevTex);}
    glBindTexture(GL_TEXTURE_2D,g_PrevTex);
    glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR);
    glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,nearestMag?GL_NEAREST:GL_LINEAR);
    glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);
    glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);
    glPixelStorei(GL_UNPACK_ALIGNMENT,4);
    static int s_AllocW = 0, s_AllocH = 0;
    if(s_AllocW != g_PrevW || s_AllocH != g_PrevH){
        glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA8,g_PrevW,g_PrevH,0,GL_RGBA,GL_UNSIGNED_BYTE,g_PrevBuf);
        s_AllocW = g_PrevW; s_AllocH = g_PrevH;
    }else{
        glTexSubImage2D(GL_TEXTURE_2D,0,0,0,g_PrevW,g_PrevH,GL_RGBA,GL_UNSIGNED_BYTE,g_PrevBuf);
    }
}

// ============ Native MP4 Export (Media Foundation Sink Writer) ============
static bool ProbeAudioFile(const char* utf8path){ // --probe-audio: verify mux output (stream presence + duration + bytes)
    MFEnsureStart();
    wchar_t wpath[MAX_PATH]={0};
    MultiByteToWideChar(CP_UTF8,0,utf8path,-1,wpath,MAX_PATH);
    IMFSourceReader* r=nullptr;
    if(FAILED(MFCreateSourceReaderFromURL(wpath,nullptr,&r))) return false;
    if(FAILED(r->SetStreamSelection((DWORD)MF_SOURCE_READER_ALL_STREAMS,FALSE))){ r->Release(); return false; }
    DWORD asi=FindAudioStream(r);
    double durSec=0; PROPVARIANT pv; PropVariantInit(&pv);
    if(SUCCEEDED(r->GetPresentationAttribute((DWORD)MF_SOURCE_READER_MEDIASOURCE,MF_PD_DURATION,&pv)) && pv.vt==VT_UI8)
        durSec=(double)pv.hVal.QuadPart/1e7;
    PropVariantClear(&pv);
    double vDurSec=durSec;
    for(DWORD si=0; si<8; si++){ // report the video stream too: verifies work-area export length
        IMFMediaType* nt=nullptr;
        if(FAILED(r->GetNativeMediaType(si,0,&nt))) continue;
        GUID maj={0}; nt->GetGUID(MF_MT_MAJOR_TYPE,&maj);
        nt->Release();
        if(maj==MFMediaType_Video){
            PROPVARIANT qv; PropVariantInit(&qv);
            if(SUCCEEDED(r->GetPresentationAttribute(si,MF_PD_DURATION,&qv)) && qv.vt==VT_UI8)
                vDurSec=(double)qv.hVal.QuadPart/1e7;
            PropVariantClear(&qv);
            break;
        }
    }
    if(asi==(DWORD)-1){ r->Release(); FILE* pf0=fopen("probe.txt","w"); if(pf0){ fprintf(pf0,"audio=0 video=%.3f\n",vDurSec); fclose(pf0); } return false; }
    r->SetStreamSelection(asi,TRUE);
    UINT32 bytesPerSec=0;
    IMFMediaType* mt=nullptr;
    if(SUCCEEDED(r->GetCurrentMediaType(asi,&mt))){
        WAVEFORMATEX* wfx=nullptr; UINT32 wsz=0;
        if(SUCCEEDED(MFCreateWaveFormatExFromMFMediaType(mt,&wfx,&wsz)) && wfx){ bytesPerSec=wfx->nAvgBytesPerSec; CoTaskMemFree(wfx); }
        mt->Release();
    }
    long long totalBytes=0;
    for(int guard=0; guard<4000; guard++){
        IMFSample* smp=nullptr; DWORD flags=0;
        r->ReadSample(asi,0,nullptr,&flags,nullptr,&smp);
        if(flags&MF_SOURCE_READERF_ENDOFSTREAM){ if(smp)smp->Release(); break; }
        if(!smp) continue;
        IMFMediaBuffer* mb=nullptr;
        if(SUCCEEDED(smp->ConvertToContiguousBuffer(&mb))){
            BYTE* data=nullptr; DWORD maxLen=0,curLen=0;
            if(SUCCEEDED(mb->Lock(&data,&maxLen,&curLen))){ totalBytes+=curLen; mb->Unlock(); }
        }
        if(mb)mb->Release();
        smp->Release();
    }
    r->Release();
    FILE* pf=fopen("probe.txt","w");
    if(pf){ fprintf(pf,"audio=1 duration=%.3f bytes=%lld bytesPerSec=%u video=%.3f\n",durSec,totalBytes,bytesPerSec,vDurSec); fclose(pf); }
    return totalBytes > 0;
}
static bool EncodeMP4(const char* utf8path){
    MFEnsureStart();
    float startT = 0.0f, dur = TotalDur();
    if(WorkAreaActive()){ startT = g_WorkIn; dur = g_WorkOut - g_WorkIn; } // export honors the work area
    if(dur<=0.01f)return false;
    long long totalFrames=(long long)(dur*g_FPS+0.5f); // float FPS: (int) truncation at 29.97 drifts content ~1s over 30s
    wchar_t wpath[MAX_PATH]={0};
    MultiByteToWideChar(CP_UTF8,0,utf8path,-1,wpath,MAX_PATH);

    IMFSinkWriter* writer=nullptr;
    IMFMediaType* outType=nullptr,*inType=nullptr;
    IMFMediaType* aOut=nullptr,*aIn=nullptr;
    DWORD stream=0, aStream=0;
    bool hasAudio=false;
    for(auto& c : g_Clips){ // mux only when there is something to mux; setup failure falls back to video-only
        if(c.videoIdx >= 0 && c.videoIdx < (int)g_Videos.size() && !g_Videos[c.videoIdx].audioPCM.empty()){ hasAudio = true; break; }
    }
    HRESULT hr=MFCreateSinkWriterFromURL(wpath,nullptr,nullptr,&writer);
    if(FAILED(hr))return false;
    UINT32 br=(UINT32)std::min(20000000.0f,std::max(2000000.0f,(float)g_CompW*g_CompH*g_FPS*0.12f));
    auto FreeAudioTypes = [&](){ if(aOut){ aOut->Release(); aOut = nullptr; } if(aIn){ aIn->Release(); aIn = nullptr; } };
    do{
        if(FAILED(MFCreateMediaType(&outType)))break;
        outType->SetGUID(MF_MT_MAJOR_TYPE,MFMediaType_Video);
        outType->SetGUID(MF_MT_SUBTYPE,MFVideoFormat_H264);
        outType->SetUINT32(MF_MT_AVG_BITRATE,br);
        outType->SetUINT32(MF_MT_INTERLACE_MODE,MFVideoInterlace_Progressive);
        MFSetAttributeSize(outType,MF_MT_FRAME_SIZE,(UINT32)g_CompW,(UINT32)g_CompH);
        MFSetAttributeRatio(outType,MF_MT_FRAME_RATE,(UINT32)(g_FPS*1000.0f+0.5f),1000);
        MFSetAttributeRatio(outType,MF_MT_PIXEL_ASPECT_RATIO,1,1);
        if(FAILED(MFCreateMediaType(&inType)))break;
        inType->SetGUID(MF_MT_MAJOR_TYPE,MFMediaType_Video);
        inType->SetGUID(MF_MT_SUBTYPE,MFVideoFormat_RGB32);
        inType->SetUINT32(MF_MT_INTERLACE_MODE,MFVideoInterlace_Progressive);
        MFSetAttributeSize(inType,MF_MT_FRAME_SIZE,(UINT32)g_CompW,(UINT32)g_CompH);
        MFSetAttributeRatio(inType,MF_MT_FRAME_RATE,(UINT32)(g_FPS*1000.0f+0.5f),1000);
        MFSetAttributeRatio(inType,MF_MT_PIXEL_ASPECT_RATIO,1,1);
        if(FAILED(writer->AddStream(outType,&stream)))break;
        if(FAILED(writer->SetInputMediaType(stream,inType,nullptr)))break;
        if(hasAudio){ // AAC audio stream (same PCM the preview mixer uses); any failure = video-only export, not a failed export
            if(SUCCEEDED(MFCreateMediaType(&aOut)) && SUCCEEDED(MFCreateMediaType(&aIn))){
                aOut->SetGUID(MF_MT_MAJOR_TYPE,MFMediaType_Audio);
                aOut->SetGUID(MF_MT_SUBTYPE,MFAudioFormat_AAC);
                aOut->SetUINT32(MF_MT_AUDIO_NUM_CHANNELS,AU_CH);
                aOut->SetUINT32(MF_MT_AUDIO_SAMPLES_PER_SECOND,AU_RATE);
                aOut->SetUINT32(MF_MT_AUDIO_AVG_BYTES_PER_SECOND,16000);
                aOut->SetUINT32(MF_MT_AAC_PAYLOAD_TYPE,0);
                aIn->SetGUID(MF_MT_MAJOR_TYPE,MFMediaType_Audio);
                aIn->SetGUID(MF_MT_SUBTYPE,MFAudioFormat_PCM);
                aIn->SetUINT32(MF_MT_AUDIO_NUM_CHANNELS,AU_CH);
                aIn->SetUINT32(MF_MT_AUDIO_SAMPLES_PER_SECOND,AU_RATE);
                aIn->SetUINT32(MF_MT_AUDIO_BITS_PER_SAMPLE,16);
                aIn->SetUINT32(MF_MT_AUDIO_BLOCK_ALIGNMENT,AU_CH*2);
                aIn->SetUINT32(MF_MT_AUDIO_AVG_BYTES_PER_SECOND,AU_RATE*AU_CH*2);
                if(SUCCEEDED(writer->AddStream(aOut,&aStream)) && SUCCEEDED(writer->SetInputMediaType(aStream,aIn,nullptr))){ /* keep hasAudio */ }
                else hasAudio = false;
            }else hasAudio = false;
            if(!hasAudio) FreeAudioTypes();
        }
        if(FAILED(writer->BeginWriting()))break;

        const int stride=g_CompW*4;
        std::vector<unsigned char> rgba((size_t)g_CompW*g_CompH*4);
        LONGLONG frameDur=(LONGLONG)(1e7/g_FPS);
        bool ok=true;
        for(long long f=0; f<totalFrames && ok; f++){
            RenderPreview(startT+(float)(f/(double)g_FPS),g_CompW,g_CompH,rgba.data());
            IMFSample* smp=nullptr;
            IMFMediaBuffer* mb=nullptr;
            if(FAILED(MFCreateSample(&smp))){ok=false;break;}
            if(FAILED(MFCreateMemoryBuffer(stride*g_CompH,&mb))){smp->Release();ok=false;break;}
            BYTE* dst=nullptr;
            if(SUCCEEDED(mb->Lock(&dst,nullptr,nullptr))){
                // top-down RGBA -> bottom-up BGRA (RGB32 DIB convention)
                for(int y=0;y<g_CompH;y++){
                    const unsigned char* src=&rgba[(size_t)((g_CompH-1-y)*(size_t)g_CompW)*4];
                    BYTE* drow=dst+(size_t)y*stride;
                    for(int x=0;x<g_CompW;x++){
                        drow[x*4+0]=src[x*4+2];
                        drow[x*4+1]=src[x*4+1];
                        drow[x*4+2]=src[x*4+0];
                        drow[x*4+3]=255;
                    }
                }
                mb->Unlock();
                mb->SetCurrentLength(stride*g_CompH);
            }
            smp->AddBuffer(mb);
            smp->SetSampleTime((LONGLONG)(f*frameDur));
            smp->SetSampleDuration(frameDur);
            if(FAILED(writer->WriteSample(stream,smp)))ok=false;
            smp->Release();mb->Release();
            if(ok && hasAudio){ // one audio packet per video frame on the same time grid
                int nSamp=(int)(AU_RATE/g_FPS+0.5f);
                static float aAcc[AU_CHUNK*2];
                int need=nSamp*2;
                if(need > AU_CHUNK*2) need = AU_CHUNK*2; // 0.25s cap per packet; low-fps edge, timestamps stay exact
                MixAudioRange(startT+(float)(f*frameDur)/1e7f, need/2, aAcc);
                IMFSample* asmp=nullptr; IMFMediaBuffer* amb=nullptr;
                if(SUCCEEDED(MFCreateSample(&asmp)) && SUCCEEDED(MFCreateMemoryBuffer(need*2,&amb))){
                    BYTE* adst=nullptr;
                    if(SUCCEEDED(amb->Lock(&adst,nullptr,nullptr))){
                        for(int i=0;i<need;i++){ short v=(short)clampf(aAcc[i]*32767.0f,-32768.0f,32767.0f); adst[i*2]=(BYTE)(v&0xFF); adst[i*2+1]=(BYTE)((v>>8)&0xFF); }
                        amb->Unlock();
                        amb->SetCurrentLength(need*2);
                    }
                    asmp->AddBuffer(amb);
                    asmp->SetSampleTime((LONGLONG)(f*frameDur));
                    asmp->SetSampleDuration((LONGLONG)((double)need/2/AU_RATE*1e7));
                    if(FAILED(writer->WriteSample(aStream,asmp)))ok=false;
                    asmp->Release();amb->Release();
                }else{ if(asmp)asmp->Release(); if(amb)amb->Release(); ok=false; }
            }
        }
        if(ok)writer->Finalize();
        writer->Release();
        if(outType)outType->Release();
        if(inType)inType->Release();
        FreeAudioTypes();
        return ok;
    }while(false);
    if(outType)outType->Release();
    if(inType)inType->Release();
    FreeAudioTypes();
    writer->Release();
    return false;
}

// ============ file io ============
static void LoadImage(ImageData&im,const char*path){
    int n=0;unsigned char*p=stbi_load(path,&im.w,&im.h,&n,4);
    if(p){im.px=p;im.path=path;}
}
static void FreeImages(){for(auto&im:g_Images){if(im.tex)glDeleteTextures(1,&im.tex);stbi_image_free(im.px);}g_Images.clear();}

static void ImportAssets(){
    HRESULT hr=CoInitializeEx(NULL,COINIT_APARTMENTTHREADED|COINIT_DISABLE_OLE1DDE);
    IFileOpenDialog*pfd=NULL;
    hr=CoCreateInstance(CLSID_FileOpenDialog,NULL,CLSCTX_ALL,IID_IFileOpenDialog,(void**)&pfd);
    if(FAILED(hr))return;
    COMDLG_FILTERSPEC filters[]={
        {L"All Supported Media",L"*.png;*.jpg;*.jpeg;*.bmp;*.tga;*.webp;*.gif;*.mp4;*.mov;*.avi;*.mkv;*.webm;*.mp3;*.wav;*.ogg;*.flac;*.m4a"},
        {L"Image Files (*.png, *.jpg, *.webp)",L"*.png;*.jpg;*.jpeg;*.bmp;*.tga;*.webp;*.gif"},
        {L"All Files (*.*)",L"*.*"},
    };
    pfd->SetFileTypes(3,filters);
    pfd->SetFileTypeIndex(1);
    pfd->SetOptions(FOS_ALLOWMULTISELECT|FOS_FILEMUSTEXIST|FOS_FORCEFILESYSTEM);
    hr=pfd->Show(NULL);
    if(FAILED(hr)){pfd->Release();CoUninitialize();return;}
    IShellItemArray*results=NULL;
    hr=pfd->GetResults(&results);
    if(FAILED(hr)){pfd->Release();CoUninitialize();return;}
    DWORD count=0;
    results->GetCount(&count);
    int added=0;
    std::vector<TimelineItem> preImport = g_Clips; // snapshot BEFORE clips are appended, so undo restores pre-import state
    float runningTimeCursor = g_PlayTime;
    for(DWORD i=0;i<count;i++){
        IShellItem*item=NULL;
        results->GetItemAt(i,&item);
        if(!item)continue;
        PWSTR pszPath=NULL;
        item->GetDisplayName(SIGDN_FILESYSPATH,&pszPath);
        if(pszPath){
            char path[MAX_PATH]={0};
            WideCharToMultiByte(CP_UTF8,0,pszPath,-1,path,sizeof(path),NULL,NULL);
            CoTaskMemFree(pszPath);
            // extension routing
            std::string lp(path);
            for(auto&ch:lp)ch=(char)tolower((unsigned char)ch);
            auto extIs = [&lp](const char* e){ size_t el=strlen(e); return lp.size()>el && lp.compare(lp.size()-el, el, e)==0; };
            bool isVideo = extIs(".mp4")||extIs(".mov")||extIs(".avi")||extIs(".mkv")||
                           extIs(".webm")||extIs(".wmv");
            bool isAudio = extIs(".mp3")||extIs(".wav")||extIs(".ogg")||extIs(".flac")||extIs(".m4a");
            // After Effects model: 1 layer contains only 1 object
            int targetTrack = 0;
            for(int tr = 0; tr < 256; tr++){
                bool occupied = false;
                for(const auto& it : g_Clips){
                    if(it.track == tr){
                        occupied = true;
                        break;
                    }
                }
                if(!occupied){
                    targetTrack = tr;
                    break;
                }
            }
            TimelineItem c;
            c.type = ITEM_MEDIA;
            c.track = targetTrack;
            EnsureTrackSize(targetTrack);
            if(isAudio){
                VideoData vd;
                if(LoadAudioOnly(vd,path)){
                    int vidIdx=(int)g_Videos.size();
                    g_Videos.push_back(vd);
                    c.videoIdx=vidIdx;
                    c.startTime = runningTimeCursor;
                    c.duration=(float)g_Videos[vidIdx].duration;
                    runningTimeCursor += c.duration;
                    g_Clips.push_back(c); added++;
                }
                item->Release();
                continue; // music/SFX live on a video-less clip: silent render, audible mix, drawn waveform
            }
            if(isVideo){
                VideoData vd;
                if(LoadVideo(vd,path)){
                    int vidIdx=(int)g_Videos.size();
                    g_Videos.push_back(vd);
                    c.videoIdx=vidIdx;
                    c.startTime = runningTimeCursor;
                    c.duration=(float)g_Videos[vidIdx].duration;
                    runningTimeCursor += c.duration;
                    g_Clips.push_back(c); added++;
                }
            }else{
                ImageData im;LoadImage(im,path);
                if(im.px){
                    UploadTex(im);
                    int imgIdx=(int)g_Images.size();
                    g_Images.push_back(im);
                    c.imageIdx = imgIdx;
                    c.startTime = runningTimeCursor;
                    c.duration = 1.0f; // Default 1.0s duration
                    runningTimeCursor += c.duration;
                    g_Clips.push_back(c);
                    added++;
                }
            }
        }
        item->Release();
    }
    results->Release();
    pfd->Release();
    CoUninitialize();
    if(added>0){
        PushUndoSnapshot(preImport);
        g_SelClip=(int)g_Clips.size()-1;
        g_Dirty=true;
    }
}

static void SaveProject(const char*path){
    // ponytail: write tmp + rename so a crash/power cut never truncates the only copy (autosave hits this every 60s)
    std::string tmp = std::string(path) + ".tmp";
    FILE*f=fopen(tmp.c_str(),"w");if(!f)return;
    fprintf(f,"AIEATOR 3\n");
    fprintf(f,"RES %d %d\n",g_CompW,g_CompH);
    fprintf(f,"FPS %.3f\n",g_FPS);
    fprintf(f,"IMAGES %d\n",(int)g_Images.size());
    for(auto&im:g_Images)fprintf(f,"IMG %s\n",im.path.c_str());
    fprintf(f,"VIDEOS %d\n",(int)g_Videos.size());
    for(auto&v:g_Videos)fprintf(f,"VID %s\n",v.path.c_str());
    fprintf(f,"CLIPS %d\n",(int)g_Clips.size());
    for(auto&c:g_Clips){
        fprintf(f,"ITEM %d %d %.3f %.3f %.3f %d %d %d %d %d %.3f %.3f\n",
            (int)c.type, c.track, c.startTime, c.duration, c.speed, c.kenBurns?1:0, 0, c.videoIdx,
            c.motionBlur?1:0, c.shutterAngle, c.opacity, c.srcOff); // trailing MB/opacity/srcOff: old readers ignore them
        fprintf(f,"MEDIA %d\n", c.imageIdx);
        fprintf(f,"CAM %.3f %.3f %.3f %.3f\n",c.cam.zoom,c.cam.px,c.cam.py,c.cam.rot);
        // ponytail: AE-exact per-property key sections, then mask
        fprintf(f,"KPOS %d\n", (int)c.kPos.size());
        for(auto& k : c.kPos) fprintf(f,"K %.3f %.3f %.3f %d %.3f %.3f %.3f %.3f %d %d %.3f %.3f %.3f %.3f\n", k.time, k.x, k.y, k.easeType, k.bezCP[0], k.bezCP[1], k.bezCP[2], k.bezCP[3], k.hold?1:0, k.inEaseType, k.inBezCP[0], k.inBezCP[1], k.inBezCP[2], k.inBezCP[3]);
        fprintf(f,"KSCL %d\n", (int)c.kScale.size());
        for(auto& k : c.kScale) fprintf(f,"K %.3f %.3f %d %.3f %.3f %.3f %.3f %d %d %.3f %.3f %.3f %.3f\n", k.time, k.value, k.easeType, k.bezCP[0], k.bezCP[1], k.bezCP[2], k.bezCP[3], k.hold?1:0, k.inEaseType, k.inBezCP[0], k.inBezCP[1], k.inBezCP[2], k.inBezCP[3]);
        fprintf(f,"KROT %d\n", (int)c.kRot.size());
        for(auto& k : c.kRot) fprintf(f,"K %.3f %.3f %d %.3f %.3f %.3f %.3f %d %d %.3f %.3f %.3f %.3f\n", k.time, k.value, k.easeType, k.bezCP[0], k.bezCP[1], k.bezCP[2], k.bezCP[3], k.hold?1:0, k.inEaseType, k.inBezCP[0], k.inBezCP[1], k.inBezCP[2], k.inBezCP[3]);
        fprintf(f,"KOP %d\n", (int)c.kOp.size());
        for(auto& k : c.kOp) fprintf(f,"K %.3f %.3f %d %.3f %.3f %.3f %.3f %d %d %.3f %.3f %.3f %.3f\n", k.time, k.value, k.easeType, k.bezCP[0], k.bezCP[1], k.bezCP[2], k.bezCP[3], k.hold?1:0, k.inEaseType, k.inBezCP[0], k.inBezCP[1], k.inBezCP[2], k.inBezCP[3]);
        fprintf(f,"COL %.3f %.3f %.3f\n",c.color.bright,c.color.contrast,c.color.sat);
        int r=(int)clampf(c.textColor[0]*255.0f,0,255);
        int g=(int)clampf(c.textColor[1]*255.0f,0,255);
        int b=(int)clampf(c.textColor[2]*255.0f,0,255);
        fprintf(f,"TXT %.1f %d %d %d %.3f %d\n",c.fontSize,r,g,b,c.textAlpha,c.fontIdx);
        fprintf(f,"TTX\n%s\n",c.textContent);
        fprintf(f,"TRN %d %.3f\n",c.transType,c.transDur);
        fprintf(f,"FX %d\n",(int)c.fx.size());
        for(auto&e:c.fx){
            fprintf(f,"FXE %d %d",e.type,e.enabled?1:0);
            for(int k=0;k<8;k++)fprintf(f," %.3f",e.p[k]);
            fprintf(f,"\n");
        }
    }
    fprintf(f,"MARKERS %d\n",(int)g_Markers.size());
    for(float m : g_Markers) fprintf(f,"MK %.3f\n",m);
    fprintf(f,"WORK %.3f %.3f\n",g_WorkIn,g_WorkOut);
    fclose(f);
    remove(path); // rename() fails if the target exists on Windows: drop it only after the tmp is fully written
    rename(tmp.c_str(), path);
}

static bool ReadLine(FILE*f,char*buf,int sz){
    if(!fgets(buf,sz,f))return false;
    return true;
}

static bool LoadProject(const char*path){
    FILE*f=fopen(path,"r");if(!f)return false;
    char line[1024];int ver=0;
    if(!ReadLine(f,line,sizeof line)||sscanf(line,"AIEATOR %d",&ver)<1){fclose(f);return false;}
    std::vector<std::string> paths;
    std::vector<std::string> vpaths;
    int clipCount=0;
    while(ReadLine(f,line,sizeof line)){
        if(sscanf(line,"RES %d %d",&g_CompW,&g_CompH)==2)continue;
        if(sscanf(line,"FPS %f",&g_FPS)==1)continue;
        int n=0;
        if(sscanf(line,"IMAGES %d",&n)==1){
            for(int i=0;i<n;i++){
                if(!ReadLine(f,line,sizeof line))break;
                std::string p=line;while(!p.empty()&&(p.back()=='\n'||p.back()=='\r'))p.pop_back();
                if(p.rfind("IMG ", 0) == 0) p = p.substr(4);
                paths.push_back(p);
            }
            continue;
        }
        if(sscanf(line,"VIDEOS %d",&n)==1){
            for(int i=0;i<n;i++){
                if(!ReadLine(f,line,sizeof line))break;
                std::string p=line;while(!p.empty()&&(p.back()=='\n'||p.back()=='\r'))p.pop_back();
                if(p.rfind("VID ", 0) == 0) p = p.substr(4);
                vpaths.push_back(p);
            }
            continue;
        }
        if(sscanf(line,"CLIPS %d",&n)==1){clipCount=n;break;}
    }
    // A hostile/broken file must not crash the renderer: RES feeds malloc sizes, FPS feeds 1/fps divides
    g_CompW=std::clamp(g_CompW,16,8192); g_CompH=std::clamp(g_CompH,16,8192);
    if(!(g_FPS>=1.0f)) g_FPS=30.0f; else if(g_FPS>240.0f) g_FPS=240.0f; // also rejects NaN
    FreeImages();FreeVideos();s_TextCache.clear();
    // Failed loads still push a placeholder: clip imageIdx/videoIdx come from the file and would
    // otherwise shift onto the WRONG media for every clip after a missing asset.
    for(auto&p:paths){ImageData im;LoadImage(im,p.c_str());if(im.px)UploadTex(im);g_Images.push_back(im);}
    for(auto&p:vpaths){VideoData vd;if(!LoadVideo(vd,p.c_str()))vd.path=p;g_Videos.push_back(vd);}
    std::vector<TimelineItem> newclips;
    for(int i=0;i<clipCount;i++){
        TimelineItem c;int kb=0,nkf=0, itype=0;
        if(!ReadLine(f,line,sizeof line))break;
        if(ver >= 3){
            int vid=-1, mb=0, sh=180; float op=1.0f, so=0.0f;
            int nf=sscanf(line,"ITEM %d %d %f %f %f %d %d %d %d %d %f %f",&itype,&c.track,&c.startTime,&c.duration,&c.speed,&kb,&nkf,&vid,&mb,&sh,&op,&so);
            if(nf<5)break;
            c.track=std::clamp(c.track,0,255); // unbounded track => per-frame scan of billions of lanes in RenderPreview
            EnsureTrackSize(c.track);
            c.videoIdx=(nf>=8)?vid:-1;
            if(nf>=9) c.motionBlur = mb!=0;
            if(nf>=10) c.shutterAngle = sh;
            if(nf>=11) c.opacity = clampf(op,0.0f,1.0f);
            if(nf>=12) c.srcOff = std::max(0.0f, so);
            c.type = (ItemType)itype;
        }else{
            if(sscanf(line,"CLIP %d %f %f %d %d",&c.imageIdx,&c.duration,&c.speed,&kb,&nkf)<4)break;
            c.track = 0;
            EnsureTrackSize(0);
            c.startTime = 0.0f;
            for(int k=0;k<i;k++) c.startTime += newclips[k].duration * std::max(0.1f, newclips[k].speed);
        }
        c.kenBurns=kb!=0;
        if(ver >= 3){
            if(!ReadLine(f,line,sizeof line)||sscanf(line,"MEDIA %d",&c.imageIdx)!=1)break;
        }
        if(!ReadLine(f,line,sizeof line)||sscanf(line,"CAM %f %f %f %f",&c.cam.zoom,&c.cam.px,&c.cam.py,&c.cam.rot)!=4)break;
        bool oldKF = false;
        if(nkf > 0){
            // legacy unified-key files: expand each key into all 4 prop lists
            for(int k=0;k<nkf;k++){
                if(!ReadLine(f,line,sizeof line))break;
                float kt=0,kz=1,kx=0,ky=0,kr=0; int ke=1; float b0=0.25f,b1=0.1f,b2=0.25f,b3=1.0f,ko=1.0f;
                int nfKF = sscanf(line,"KF %f %f %f %f %f %d %f %f %f %f %f",
                    &kt,&kz,&kx,&ky,&kr,&ke,&b0,&b1,&b2,&b3,&ko);
                if(nfKF >= 6){
                    if(nfKF < 11) oldKF = true;
                    Key2D kp; kp.time=kt; kp.x=kx; kp.y=ky; kp.easeType=ke; kp.bezCP[0]=b0; kp.bezCP[1]=b1; kp.bezCP[2]=b2; kp.bezCP[3]=b3; c.kPos.push_back(kp);
                    Key1D ks; ks.time=kt; ks.value=kz; ks.easeType=ke; ks.bezCP[0]=b0; ks.bezCP[1]=b1; ks.bezCP[2]=b2; ks.bezCP[3]=b3; c.kScale.push_back(ks);
                    Key1D kr2; kr2.time=kt; kr2.value=kr; kr2.easeType=ke; kr2.bezCP[0]=b0; kr2.bezCP[1]=b1; kr2.bezCP[2]=b2; kr2.bezCP[3]=b3; c.kRot.push_back(kr2);
                    Key1D ko2; ko2.time=kt; ko2.value=ko; ko2.easeType=ke; ko2.bezCP[0]=b0; ko2.bezCP[1]=b1; ko2.bezCP[2]=b2; ko2.bezCP[3]=b3; c.kOp.push_back(ko2);
                }
            }
            // optional legacy KPM line (ignored); else next line is COL
            if(!ReadLine(f,line,sizeof line))break;
            if(strncmp(line,"KPM",3)==0){
                if(!ReadLine(f,line,sizeof line))break;
            }
        }else{
            // per-prop sections (new files) or straight to COL (old keyless files)
            if(!ReadLine(f,line,sizeof line))break;
            if(strncmp(line,"KPOS",4)==0){
                int nn = 0;
                if(sscanf(line,"KPOS %d",&nn)==1) for(int k=0;k<nn;k++){
                    if(!ReadLine(f,line,sizeof line))break;
                    Key2D kp; int ke = 1;
                    int hd=0, ie=0; float ib0=0,ib1=0,ib2=1,ib3=1;
                    int nfP=sscanf(line,"K %f %f %f %d %f %f %f %f %d %d %f %f %f %f",&kp.time,&kp.x,&kp.y,&ke,&kp.bezCP[0],&kp.bezCP[1],&kp.bezCP[2],&kp.bezCP[3],&hd,&ie,&ib0,&ib1,&ib2,&ib3);
                    if(nfP>=4){ kp.easeType=ke; if(nfP>=10){ kp.hold=hd!=0; kp.inEaseType=ie; } if(nfP>=14){ kp.inBezCP[0]=ib0; kp.inBezCP[1]=ib1; kp.inBezCP[2]=ib2; kp.inBezCP[3]=ib3; } c.kPos.push_back(kp); }
                }
                if(!ReadLine(f,line,sizeof line)||sscanf(line,"KSCL %d",&nn)!=1)break;
                for(int k=0;k<nn;k++){
                    if(!ReadLine(f,line,sizeof line))break;
                    Key1D kk; int ke = 1;
                    int hd=0, ie=0; float ib0=0,ib1=0,ib2=1,ib3=1;
                    int nfS=sscanf(line,"K %f %f %d %f %f %f %f %d %d %f %f %f %f",&kk.time,&kk.value,&ke,&kk.bezCP[0],&kk.bezCP[1],&kk.bezCP[2],&kk.bezCP[3],&hd,&ie,&ib0,&ib1,&ib2,&ib3);
                    if(nfS>=3){ kk.easeType=ke; if(nfS>=9){ kk.hold=hd!=0; kk.inEaseType=ie; } if(nfS>=13){ kk.inBezCP[0]=ib0; kk.inBezCP[1]=ib1; kk.inBezCP[2]=ib2; kk.inBezCP[3]=ib3; } c.kScale.push_back(kk); }
                }
                if(!ReadLine(f,line,sizeof line)||sscanf(line,"KROT %d",&nn)!=1)break;
                for(int k=0;k<nn;k++){
                    if(!ReadLine(f,line,sizeof line))break;
                    Key1D kk; int ke = 1;
                    int hd=0, ie=0; float ib0=0,ib1=0,ib2=1,ib3=1;
                    int nfR=sscanf(line,"K %f %f %d %f %f %f %f %d %d %f %f %f %f",&kk.time,&kk.value,&ke,&kk.bezCP[0],&kk.bezCP[1],&kk.bezCP[2],&kk.bezCP[3],&hd,&ie,&ib0,&ib1,&ib2,&ib3);
                    if(nfR>=3){ kk.easeType=ke; if(nfR>=9){ kk.hold=hd!=0; kk.inEaseType=ie; } if(nfR>=13){ kk.inBezCP[0]=ib0; kk.inBezCP[1]=ib1; kk.inBezCP[2]=ib2; kk.inBezCP[3]=ib3; } c.kRot.push_back(kk); }
                }
                if(!ReadLine(f,line,sizeof line)||sscanf(line,"KOP %d",&nn)!=1)break;
                for(int k=0;k<nn;k++){
                    if(!ReadLine(f,line,sizeof line))break;
                    Key1D kk; int ke = 1;
                    int hd=0, ie=0; float ib0=0,ib1=0,ib2=1,ib3=1;
                    int nfO=sscanf(line,"K %f %f %d %f %f %f %f %d %d %f %f %f %f",&kk.time,&kk.value,&ke,&kk.bezCP[0],&kk.bezCP[1],&kk.bezCP[2],&kk.bezCP[3],&hd,&ie,&ib0,&ib1,&ib2,&ib3);
                    if(nfO>=3){ kk.easeType=ke; if(nfO>=9){ kk.hold=hd!=0; kk.inEaseType=ie; } if(nfO>=13){ kk.inBezCP[0]=ib0; kk.inBezCP[1]=ib1; kk.inBezCP[2]=ib2; kk.inBezCP[3]=ib3; } c.kOp.push_back(kk); }
                }
                if(!ReadLine(f,line,sizeof line))break;
                if(strncmp(line,"KPM",3)==0){ if(!ReadLine(f,line,sizeof line))break; } // legacy, ignored
            }
        }
        if(sscanf(line,"COL %f %f %f",&c.color.bright,&c.color.contrast,&c.color.sat)!=3)break;
        int on=0,r=0,g=0,b=0,fidx=0;
        if(!ReadLine(f,line,sizeof line))break;
        if(ver >= 3){
            if(sscanf(line,"TXT %f %d %d %d %f %d",&c.fontSize,&r,&g,&b,&c.textAlpha,&fidx)>=5){
                c.textColor[0]=r/255.0f;c.textColor[1]=g/255.0f;c.textColor[2]=b/255.0f;
                c.fontIdx=std::clamp(fidx, 0, std::max(0, (int)g_AvailableFonts.size()-1));
            }
        }else{
            float dummyX=0, dummyY=0;
            if(sscanf(line,"TXT %d %f %f %f %d %d %d %f %d",&on,&c.fontSize,&dummyX,&dummyY,&r,&g,&b,&c.textAlpha,&fidx)>=8){
                c.textColor[0]=r/255.0f;c.textColor[1]=g/255.0f;c.textColor[2]=b/255.0f;
                c.fontIdx=std::clamp(fidx, 0, std::max(0, (int)g_AvailableFonts.size()-1));
            }
        }
        if(oldKF){ for(auto& k : c.kOp) k.value = c.textAlpha; } // pre-opacity files: opacity keys inherit layer opacity
        if(!ReadLine(f,line,sizeof line)||strncmp(line,"TTX",3)!=0)break;
        if(!ReadLine(f,line,sizeof line))break;
        {char*e=line+strlen(line);while(e>line&&(e[-1]=='\n'||e[-1]=='\r'))*--e=0;
        snprintf(c.textContent,sizeof c.textContent,"%s",line);}
        if(!ReadLine(f,line,sizeof line)||sscanf(line,"TRN %d %f",&c.transType,&c.transDur)!=2)break;
        int nfx=0;
        if(!ReadLine(f,line,sizeof line)||sscanf(line,"FX %d",&nfx)!=1)break;
        for(int k=0;k<nfx;k++){
            FXParams e;int et=0,en=0;
            if(!ReadLine(f,line,sizeof line)||sscanf(line,"FXE %d %d %f %f %f %f %f %f %f %f",&et,&en,&e.p[0],&e.p[1],&e.p[2],&e.p[3],&e.p[4],&e.p[5],&e.p[6],&e.p[7])!=10)break;
            e.type=et;e.enabled=en!=0;c.fx.push_back(e);
        }
        newclips.push_back(c);
    }
    std::vector<float> newmarkers;
    float wIn = -1.0f, wOut = -1.0f;
    while(ReadLine(f,line,sizeof line)){ // trailing MARKERS/WORK trailer (absent in old files: defaults stand)
        int nm = 0;
        if(sscanf(line,"MARKERS %d",&nm)==1){
            for(int k = 0; k < nm && ReadLine(f,line,sizeof line); k++){
                float mt = 0; if(sscanf(line,"MK %f",&mt)==1 && mt >= 0.0f) newmarkers.push_back(mt);
            }
            continue;
        }
        if(sscanf(line,"WORK %f %f",&wIn,&wOut)==2) continue;
    }
    fclose(f);
    g_Clips=newclips;
    g_Markers=newmarkers;
    std::sort(g_Markers.begin(), g_Markers.end());
    if(wIn >= 0.0f && wOut > wIn){ g_WorkIn = wIn; g_WorkOut = wOut; } else{ g_WorkIn = -1.0f; g_WorkOut = -1.0f; }
    g_SelClip=(g_Clips.size() > 1) ? 1 : (g_Clips.empty() ? -1 : 0);g_PlayTime=0;g_Dirty=true;
    // project-scoped state must not leak across a load: undo would restore the OLD project's
    // clips (whose media indices now point into the NEW project's arrays), and a stale
    // g_SelMulti makes Delete erase wrong clips
    g_Undo.clear();g_Redo.clear();g_SelMulti.clear();g_SelKey=-1;g_SelKeyProp=-1;
    g_AppState=STATE_STUDIO;
    return true;
}

static void OpenProject(){
    HRESULT hr=CoInitializeEx(NULL,COINIT_APARTMENTTHREADED|COINIT_DISABLE_OLE1DDE);
    IFileOpenDialog*pfd=NULL;
    hr=CoCreateInstance(CLSID_FileOpenDialog,NULL,CLSCTX_ALL,IID_IFileOpenDialog,(void**)&pfd);
    if(FAILED(hr))return;
    COMDLG_FILTERSPEC filters[]={
        {L"Aieator Project (*.aie)",L"*.aie"},
        {L"All Files (*.*)",L"*.*"},
    };
    pfd->SetFileTypes(2,filters);
    pfd->SetFileTypeIndex(1);
    pfd->SetOptions(FOS_FILEMUSTEXIST|FOS_FORCEFILESYSTEM);
    hr=pfd->Show(NULL);
    if(FAILED(hr)){pfd->Release();CoUninitialize();return;}
    IShellItem*item=NULL;
    hr=pfd->GetResult(&item);
    if(SUCCEEDED(hr)){
        PWSTR pszPath=NULL;
        item->GetDisplayName(SIGDN_FILESYSPATH,&pszPath);
        if(pszPath){
            char path[MAX_PATH]={0};
            WideCharToMultiByte(CP_UTF8,0,pszPath,-1,path,sizeof(path),NULL,NULL);
            CoTaskMemFree(pszPath);
            if(LoadProject(path)){ g_ProjectPath = path; g_AppState = STATE_STUDIO; }
        }
        item->Release();
    }
    pfd->Release();
    CoUninitialize();
}

static void SaveProjectDialog(){
    HRESULT hr=CoInitializeEx(NULL,COINIT_APARTMENTTHREADED|COINIT_DISABLE_OLE1DDE);
    IFileSaveDialog*pfd=NULL;
    hr=CoCreateInstance(CLSID_FileSaveDialog,NULL,CLSCTX_ALL,IID_IFileSaveDialog,(void**)&pfd);
    if(FAILED(hr))return;
    COMDLG_FILTERSPEC filters[]={
        {L"Aieator Project (*.aie)",L"*.aie"},
    };
    pfd->SetFileTypes(1,filters);
    pfd->SetFileTypeIndex(1);
    pfd->SetDefaultExtension(L"aie");
    pfd->SetOptions(FOS_OVERWRITEPROMPT|FOS_FORCEFILESYSTEM);
    hr=pfd->Show(NULL);
    if(FAILED(hr)){pfd->Release();CoUninitialize();return;}
    IShellItem*item=NULL;
    hr=pfd->GetResult(&item);
    if(SUCCEEDED(hr)){
        PWSTR pszPath=NULL;
        item->GetDisplayName(SIGDN_FILESYSPATH,&pszPath);
        if(pszPath){
            char path[MAX_PATH]={0};
            WideCharToMultiByte(CP_UTF8,0,pszPath,-1,path,sizeof(path),NULL,NULL);
            CoTaskMemFree(pszPath);
            SaveProject(path);
            g_ProjectPath = path;
        }
        item->Release();
    }
    pfd->Release();
    CoUninitialize();
}

